import { chapter, choice, e, field, interval, n, q, roots, section, unit } from "../math/authoring.ts";
import type { MathCourse } from "../math/types.ts";
import { math1011 } from "./math1011.ts";

const fn = (id:string,prompt:string,answer:string,hint:string,solution:string[]) => q(id,prompt,[field("Expression in x",answer,"function")],hint,solution);
const pick = (id:string,prompt:string,answer:string,options:string[],hint:string,solution:string[]) => q(id,prompt,[choice("Your answer",answer,options)],hint,solution);

// Chapters are assembled in prerequisite order at the end of this file.
const transcendental = chapter("c-transcendental","Trigonometric, Exponential & Logarithmic Derivatives","Extend differentiation to the function families learned in Precalculus.",[
  section({id:"c-trig-derivatives",title:"Trigonometric Rates in Radians",teaches:["trig-derivatives"],requires:["chain-rule","product-rule","trig-identities"],
    paragraphs:["The basic derivatives are (sin x)'=cos x and (cos x)'=-sin x. These formulas assume radians: the limiting ratio sin(h)/h tends to 1 when h is in radians, not degrees. The negative sign for cosine matches its falling graph near a small positive angle. A periodic function can have a changing rate even though its values stay bounded.","The other four rules follow from the quotient rule and reciprocal identities: tan differentiates to sec squared, cot to negative csc squared, sec to sec times tan, and csc to negative csc times cot. Keep each function's domain restrictions. When the angle is a function of x, multiply by its derivative; when a trig function is multiplied by x, include both product-rule contributions."],
    rules:["(sin x)'=cos x; (cos x)'=-sin x; (tan x)'=sec(x)^2.","(cot x)'=-csc(x)^2; (sec x)'=sec(x)tan(x); (csc x)'=-csc(x)cot(x).","lim sin(h)/h=1 and lim (cos(h)-1)/h=0 as h→0 in radians."],
    examples:[{problem:"Differentiate sin(4x).",steps:["The outer derivative is cos(4x).","The angle changes at rate 4, giving 4cos(4x)."]},{problem:"Differentiate x cos(x).",steps:["Use a product rule, not just a trig rule.","The derivative is cos(x)-x sin(x)."]}],misconception:"cos(x^2) and cos(x)^2 have different layers and therefore different derivatives.",
    questions:[fn("c-trigd-1","Differentiate 3sin(x)-2cos(x).","3*cos(x)+2*sin(x)","Remember cosine's negative derivative.",["3cos(x)-2(-sin(x))=3cos(x)+2sin(x)."]),fn("c-trigd-2","Differentiate cos(5x).","-5*sin(5*x)","Include the sign and angle rate.",["-sin(5x)·5."]),fn("c-trigd-3","Differentiate sin(x^2).","2*x*cos(x^2)","The inner function is x^2.",["cos(x^2)·2x."]),fn("c-trigd-4","Differentiate sin(x)^2.","2*sin(x)*cos(x)","The outer function is a square.",["2sin(x)·cos(x)."]),fn("c-trigd-5","Differentiate tan(2x), where defined.","2*sec(2*x)^2","Differentiate the angle too.",["sec(2x)^2·2."]),fn("c-trigd-6","Differentiate sec(x)+csc(x), where defined.","sec(x)*tan(x)-csc(x)*cot(x)","The csc derivative carries a minus sign.",["Use the two reciprocal-function derivative rules."]),fn("c-trigd-7","Differentiate x^2 sin(x).","2*x*sin(x)+x^2*cos(x)","Both factors change.",["The product rule gives the displayed two contributions."]),n("c-trigd-8","Evaluate lim sin(3x)/x as x→0, in radians.","3","Create a denominator of 3x.",["sin(3x)/x=3sin(3x)/(3x), whose limit is 3."])]}),
  section({id:"c-exp-log",title:"Exponential & Logarithmic Rates",teaches:["exp-log-derivatives","logarithmic-differentiation"],requires:["chain-rule","product-rule","log-laws"],
    paragraphs:["The natural exponential has a special rate: the derivative of e^x is e^x itself. For a positive base a other than 1, write a^x=e^(x ln a); the chain rule gives a^x ln a. An exponential's variable is in its exponent, unlike the fixed exponent in a power function. Mixing those two structures leads to different and incompatible rules.","Because ln is the inverse of the natural exponential, its derivative is 1/x for x>0. Composition gives d ln(u)/dx=u'/u on u>0; ln|u| has the same derivative wherever u≠0. For log base a, divide by ln a. Logarithmic differentiation means taking logs of a positive function, using log laws to simplify products or variable exponents, differentiating, and finally multiplying back by y. It is especially helpful when both the base and exponent vary."],
    rules:["(e^u)'=e^u u'; (a^x)'=a^x ln(a).","(ln u)'=u'/u; (log(u))'=u'/(u ln(10)) for base-10 log.","For y>0, differentiating ln(y) gives y'/y. On x>0, (x^x)'=x^x(ln x+1)."],
    examples:[{problem:"Differentiate e^(3x-1).",steps:["The inner derivative is 3.","The result is 3e^(3x-1)."]},{problem:"Differentiate ln(x^2+1).",steps:["Use the inside derivative over the inside.","The result is 2x/(x^2+1)."]},{problem:"Find the derivative of x^x at x=1.",steps:["ln y=x ln x, so y'/y=ln x+1.","At x=1, y=1 and y'=1."]}],misconception:"The derivative of ln(x) is 1/x, not 1/ln(x); differentiating e^x does not lower its exponent.",
    questions:[fn("c-explog-1","Differentiate e^(-2x).","-2*exp(-2*x)","Use the inner rate -2.",["e^(-2x)·(-2)."]),fn("c-explog-2","Differentiate 5^x.","5^x*ln(5)","This is exponential, not a power of x.",["a^x differentiates to a^x ln(a)."]),fn("c-explog-3","Differentiate ln(3x+2), x>-2/3.","3/(3*x+2)","Inside derivative divided by inside.",["3/(3x+2)."]),fn("c-explog-4","Differentiate log(x), the base-10 logarithm, for x>0.","1/(x*ln(10))","Use change of base.",["log(x)=ln(x)/ln(10), so its derivative is 1/(x ln(10))."]),fn("c-explog-5","Differentiate x e^x.","exp(x)*(x+1)","Use both product terms.",["e^x+x e^x=e^x(1+x)."]),fn("c-explog-6","Differentiate ln(sqrt(x)), x>0.","1/(2*x)","A log law is also a valid route.",["ln(sqrt(x))=(1/2)ln(x), yielding 1/(2x)."]),n("c-explog-7","For y=x^x on x>0, find y' at x=2.","4*(ln(2)+1)","Differentiate ln y=x ln x, then multiply by y.",["y'=x^x(ln x+1); y'(2)=4(ln 2+1)."]),n("c-explog-8","P(t)=100e^(0.2t). Find its instantaneous growth rate at t=0.","20","Differentiate before evaluating.",["P'=20e^(0.2t), so P'(0)=20 population units per time unit."])]}),
  section({id:"c-inverse-derivatives",title:"Inverse Functions & Inverse Trig Rates",teaches:["inverse-derivatives"],requires:["chain-rule","trig-derivatives","inverse-functions","inverse-trig"],
    paragraphs:["An inverse function reverses input and output. Differentiate f(f^(-1)(x))=x to get f'(f^(-1)(x)) times the inverse's derivative equal to 1. Thus the inverse slope is the reciprocal of the original slope at the corresponding point, provided that original slope is not zero. The point matters: inverse slope at output b uses the original slope at input a where f(a)=b.","Applying this relationship to the restricted trig functions yields inverse trig derivatives. For arcsin and arccos the denominator is sqrt(1-x^2), with opposite signs, and finite derivatives require -1<x<1. Arctan's derivative is 1/(1+x^2) for every real x. The parser calls these asin, acos, and atan. An inverse function is not a reciprocal: asin(x) is an angle, while 1/sin(x) is csc(x)."],
    rules:["If f(a)=b and f'(a)≠0, then (f^(-1))'(b)=1/f'(a).","(asin x)'=1/sqrt(1-x^2); (acos x)'=-1/sqrt(1-x^2).","(atan x)'=1/(1+x^2); apply the chain rule to a changing input."],
    examples:[{problem:"f(2)=7 and f'(2)=4. Find the inverse slope at 7.",steps:["The corresponding original input is 2.","The inverse slope is 1/4."]},{problem:"Differentiate atan(3x).",steps:["Use 1/(1+u^2) with u=3x.","Multiply by 3 to get 3/(1+9x^2)."]}],misconception:"The notation sin^(-1) means inverse sine in this context, not the reciprocal of sine.",
    questions:[n("c-invd-1","f is invertible, f(3)=8, and f'(3)=-2. Find (f^(-1))'(8).","-1/2","Use the corresponding point.",["The inverse derivative is 1/(-2)."]),fn("c-invd-2","Differentiate asin(x/2), for -2<x<2.","1/(2*sqrt(1-x^2/4))","The inner derivative is 1/2.",["(1/2)/sqrt(1-(x/2)^2)."]),fn("c-invd-3","Differentiate acos(x), for -1<x<1.","-1/sqrt(1-x^2)","Keep the negative sign.",["Arccos decreases on its domain."]),fn("c-invd-4","Differentiate atan(x^2).","2*x/(1+x^4)","Square the entire inner input in the denominator.",["2x/(1+(x^2)^2)=2x/(1+x^4)."]),n("c-invd-5","Find the derivative of asin(x) at x=0.","1","Evaluate its derivative formula.",["1/sqrt(1-0)=1."]),pick("c-invd-6","For an invertible differentiable f, f'(a)=0. Does the reciprocal-slope formula guarantee a finite inverse derivative at f(a)?","No",["Yes, the inverse derivative is 0","No"],"Its denominator would be zero.",["The nonzero-slope hypothesis fails; no finite inverse derivative is guaranteed."])]})
],[fn("c-trans-r1","Differentiate e^x sin(x).","exp(x)*(sin(x)+cos(x))","Identify the overall product.",["e^x sin(x)+e^x cos(x)."]),fn("c-trans-r2","Differentiate ln(1+x^2)+atan(x).","(2*x+1)/(1+x^2)","Add the two derivative contributions.",["2x/(1+x^2)+1/(1+x^2)."]),n("c-trans-r3","f(x)=sin(2x)+e^x. Find the tangent slope at x=0.","3","Use radians and differentiate both terms.",["f'=2cos(2x)+e^x; at zero this is 2+1=3."])]);

const rates = chapter("c-rates","Implicit Relationships & Changing Quantities","Use derivatives when a formula is not already solved for its output.",[
 section({id:"c-implicit",title:"Implicit Differentiation",teaches:["implicit-differentiation"],requires:["chain-rule","product-rule","exp-log-derivatives"],
 paragraphs:["An equation such as x^2+y^2=25 describes a curve without giving one global function y=f(x). Near many points it still defines a local branch. Differentiate both sides with respect to x, treating y as a changing function of x. The derivative of y^2 is therefore 2y*y', not 2y, and the derivative of xy needs a product rule.","After differentiating, collect every term containing y' on one side and factor it out. Solve for y' only then. To find a slope at a specified point, substitute both coordinates into the derivative relationship. Verify that the point is on the original curve. A zero denominator in the solved slope needs geometric interpretation; it does not mean the slope is zero."],
 rules:["d(y^n)/dx=n*y^(n-1)*y'; d(xy)/dx=y+x*y'.","Differentiate the relationship before inserting the point's constant coordinates.","A tangent line uses y-y0=m(x-x0) once its slope exists."],
 examples:[{problem:"Find the slope of x^2+y^2=25 at (3,4).",steps:["2x+2yy'=0, so y'=-x/y.","At (3,4), y'=-3/4."]},{problem:"Find the slope of xy=6 at (2,3).",steps:["y+xy'=0, so y'=-y/x.","At the point, y'=-3/2."]}],misconception:"Substituting x=3 and y=4 before differentiating turns a changing equation into constants and loses the rate information.",
 questions:[n("c-impl-1","Find dy/dx for x^2+y^2=25 at (4,3).","-4/3","Differentiate before substituting.",["2x+2yy'=0 gives -x/y=-4/3."]),n("c-impl-2","Find dy/dx for xy=12 at (3,4).","-4/3","Use a product rule.",["y+xy'=0; y'=-4/3."]),n("c-impl-3","Find dy/dx for x^2+xy+y^2=7 at (1,2).","-4/5","Collect both terms containing y'.",["2x+y+xy'+2yy'=0; y'=-(2x+y)/(x+2y)=-4/5."]),e("c-impl-4","Give the tangent line's y-expression for x^2+y^2=25 at (3,-4).","3*x/4-25/4","Use the lower branch's slope.",["y'=-3/(-4)=3/4; y+4=(3/4)(x-3)."]),n("c-impl-5","Find dy/dx for e^y=x at (1,0).","1","Differentiate e^y using the chain rule.",["e^y y'=1; y'=1 at y=0."]),pick("c-impl-6","On x^2+y^2=25 at (5,0), is the tangent horizontal or vertical?","Vertical",["Horizontal","Vertical"],"The circle is at its rightmost point.",["2x+2yy'=0 cannot have a finite y' here; the tangent line is x=5."])]}),
 section({id:"c-related",title:"Related Rates & Units",teaches:["related-rates"],requires:["implicit-differentiation","calculus-change"],
 paragraphs:["In a related-rates problem, several quantities depend on time but are connected by geometry or another fixed relationship. Identify the variables, the equation connecting them, the known rates, and the instant where a rate is requested. Differentiate the general relationship with respect to time before inserting the instant's lengths or volumes. A fixed constant can be substituted earlier; a changing quantity cannot.","Rate signs carry meaning: a shrinking radius has a negative dr/dt even though the radius itself is positive. Units also change through differentiation: a volume rate is cubic units per time, not length per time. Diagrams can help, but every problem here gives its full geometric facts. The method transfers from circles and spheres to ladders, moving points, and rates of production without adding a new derivative rule."],
 rules:["For circle area A=pi*r^2, dA/dt=2pi*r*dr/dt.","For sphere volume V=4pi*r^3/3, dV/dt=4pi*r^2*dr/dt.","For x^2+y^2=L^2 with fixed L, x dx/dt+y dy/dt=0."],
 examples:[{problem:"A circle's radius grows at 2 cm/s. How fast is area growing when r=3 cm?",steps:["dA/dt=2pi*r*dr/dt.","At this instant, dA/dt=12pi cm²/s."]},{problem:"A 5 m ladder has base distance x=3 m moving away at 1 m/s. Find its top's vertical rate.",steps:["The height is y=4 since x²+y²=25.","3(1)+4y'=0, so y'=-3/4 m/s."]}],misconception:"The requested instant's value r=3 is not a constant radius throughout time.",
 questions:[n("c-rate-1","A circle's radius increases at 3 cm/s. Find dA/dt in cm²/s when r=4 cm.","24*pi","Use A=pi*r².",["2pi(4)(3)=24pi."]),n("c-rate-2","A sphere's volume increases at 12pi cm³/s. Find dr/dt when r=2 cm.","3/4","Solve the differentiated volume equation for the radius rate.",["12pi=4pi(2²)r', so r'=3/4."]),n("c-rate-3","A 10 m ladder's base is 6 m from a wall and moves away at 2 m/s. Find the top's vertical rate in m/s.","-3/2","First find the current height.",["y=8; 6(2)+8y'=0, so y'=-12/8."]),n("c-rate-4","A rectangle has length 5 m and width 3 m. At that instant length grows at 2 m/s and width shrinks at 1 m/s. Find area rate in m²/s.","1","Both dimensions change.",["A'=L'W+LW'=2(3)+5(-1)=1."]),n("c-rate-5","Two perpendicular roads meet at O. At one instant cars are 3 km east and 4 km north of O, moving away at 2 and 1 km/h. Find their separation rate in km/h.","2","Differentiate z²=x²+y².",["z=5; zz'=xx'+yy'=3(2)+4(1)=10; z'=2."]),n("c-rate-6","A balloon remains spherical. Its radius is 3 cm and shrinking at 0.5 cm/s. Find volume rate in cm³/s.","-18*pi","The radius rate is negative.",["4pi(3²)(-0.5)=-18pi."])]}),
 section({id:"c-linearization",title:"Local Linear Approximation",teaches:["linearization","differentials"],requires:["tangent-lines","chain-rule"],
 paragraphs:["A differentiable function resembles its tangent line over a sufficiently small interval. Near a, replace f(x) by L(x)=f(a)+f'(a)(x-a). This linearization turns a difficult nearby evaluation into a known value plus slope times a small input change. It is an approximation, not a new exact identity, and it becomes less dependable as the point moves away from a.","Differential notation isolates the estimated change: dy=f'(a)dx. The actual change is Δy=f(a+dx)-f(a), and these need not be identical. Choose a nearby base point where the function and derivative are easy to evaluate. In measurement problems, a small input error can then be converted into an approximate output error with units. Keep the sign if direction matters, or take an absolute value for an error magnitude."],
 rules:["L(x)=f(a)+f'(a)(x-a).","dy=f'(a)dx approximates Δy for a small dx.","Approximation does not guarantee exact equality or accuracy far from a."],
 examples:[{problem:"Approximate sqrt(4.04) using a=4.",steps:["f(4)=2 and f'(4)=1/4.","L(4.04)=2+(1/4)(0.04)=2.01."]},{problem:"Estimate the change in x³ near x=2 when dx=0.01.",steps:["f'(2)=3·2²=12.","dy=12(0.01)=0.12."]}],misconception:"The linear estimate is not obtained by plugging dx into the original function.",
 questions:[e("c-lin-1","Give L(x) for f(x)=x^2 at a=3.","6*x-9","Use the value and slope at 3.",["L=9+6(x-3)=6x-9."]),n("c-lin-2","Use linearization at a=9 to approximate sqrt(9.06). Enter the linear estimate, not the exact root.","3.01","The derivative at 9 is 1/6.",["3+(1/6)(0.06)=3.01."]),n("c-lin-3","Use linearization at a=0 to approximate e^0.02. Enter the linear estimate.","1.02","Value and slope at zero are both 1.",["L(x)=1+x, yielding 1.02."]),n("c-lin-4","For y=x^3 at x=2 with dx=-0.02, find dy.","-0.24","Keep the input change's sign.",["dy=3(2²)(-0.02)=-0.24."]),n("c-lin-5","A circle's measured radius is 10 cm, with a small radius error magnitude of 0.02 cm. Estimate area error magnitude in cm² using differentials.","0.4*pi","Differentiate area with respect to radius.",["|dA|=2pi(10)(0.02)=0.4pi."])]})
],[n("c-rates-r1","For x^2+4y^2=20 at (2,2), find dy/dx.","-1/4","Differentiate the entire equation.",["2x+8yy'=0; y'=-x/(4y)=-1/4."]),n("c-rates-r2","A circular puddle has area growing at 10pi m²/min when its radius is 5 m. Find the radius rate in m/min.","1","Relate area rate to radius rate.",["10pi=2pi(5)r', so r'=1."]),n("c-rates-r3","Use the tangent approximation to ln(x) at x=1 to estimate ln(1.03).","0.03","ln(1)=0 and its derivative there is 1.",["L(x)=x-1, so the estimate is 0.03."])]);

const extrema = chapter("c-extrema","Extrema & the Mean Value Theorem","Separate candidates from conclusions and know what each theorem guarantees.",[
 section({id:"c-extreme-values",title:"Critical Points & Absolute Extrema",teaches:["critical-points","absolute-extrema"],requires:["differentiability","power-rule"],
 paragraphs:["A local maximum is highest relative to sufficiently nearby inputs; an absolute maximum is highest over the entire domain under discussion. The Extreme Value Theorem guarantees an absolute maximum and minimum for a continuous function on a closed, bounded interval. Removing continuity or an endpoint can remove that guarantee. The theorem establishes existence; calculating the locations is a separate job.","At an interior local extremum where the derivative exists, that derivative is zero. Critical numbers are domain inputs where f' is zero or does not exist. They are candidates, not automatic extrema: x³ has a horizontal tangent at zero without turning. On a closed interval, evaluate the original function at every interior critical number and both endpoints. Compare output values, and distinguish the location x from the extreme value f(x)."],
 rules:["A continuous function on [a,b] attains absolute minimum and maximum values.","Critical numbers are domain points where f'=0 or f' does not exist.","Closed-interval method: candidates inside, endpoints, then compare original outputs."],
 examples:[{problem:"Find absolute extrema of f(x)=x²-4x on [0,3].",steps:["f'=2x-4=0 at x=2.","f(0)=0, f(2)=-4, f(3)=-3. The minimum is -4 at 2; maximum is 0 at 0."]},{problem:"Is x=0 a critical number of |x|?",steps:["The function is defined there but the derivative does not exist.","It is a critical number and, from the graph or values, an absolute minimum."]}],misconception:"Solving f'(x)=0 alone misses corners, endpoints, and the comparison needed for absolute extrema.",
 questions:[roots("c-ext-1","Find all critical numbers of f(x)=x^3-3x.","-1,1","Solve f'=0; this polynomial has a derivative everywhere.",["3x²-3=0 gives x=±1."]),q("c-ext-2","For f(x)=x²-6x+2 on [0,5], give the absolute minimum location and value.",[field("x at minimum","3"),field("Minimum value","-7")],"Check endpoints as well as the critical point.",["Candidates 0,3,5 give outputs 2,-7,-3. The least is -7 at 3."]),q("c-ext-3","Find the absolute maximum location and value for f(x)=x³-3x on [0,3].",[field("x at maximum","3"),field("Maximum value","18")],"The interior critical point is only one candidate.",["f(0)=0, f(1)=-2, f(3)=18. The maximum is 18 at 3."]),n("c-ext-4","How many critical numbers does f(x)=|x-2| have?","1","Count domain points with zero or nonexistent derivative.",["Only x=2, where the derivative does not exist."]),pick("c-ext-5","Does f'(a)=0 by itself prove a local extremum?","No",["Yes","No"],"Consider x³ at zero.",["A horizontal tangent can occur while the function keeps increasing."]),pick("c-ext-6","Does f(x)=x on the open interval (0,1) attain an absolute maximum?","No",["Yes, at x=1","No"],"The endpoint 1 is excluded.",["Every allowed input has a larger allowed input; no maximum is attained."])]}),
 section({id:"c-mvt",title:"Rolle's Theorem & the Mean Value Theorem",teaches:["mean-value-theorem","rolles-theorem"],requires:["absolute-extrema","continuity","derivative-definition"],
 paragraphs:["Rolle's theorem says that if a function is continuous on [a,b], differentiable on (a,b), and has equal endpoint values, then some interior tangent is horizontal. The picture is a smooth trip that returns to the same height. The hypotheses matter: a sharp V returns to its starting height without a horizontal tangent, because it is not differentiable at the corner.","The Mean Value Theorem removes the equal-endpoint condition. Under the same continuity and differentiability requirements, some interior tangent slope equals the secant slope (f(b)-f(a))/(b-a). For motion, some instantaneous velocity must equal the average velocity. The theorem guarantees at least one such input, not exactly one. It also explains why a derivative that is positive throughout an interval forces increasing function values there."],
 rules:["MVT: f'(c)=(f(b)-f(a))/(b-a) for some a<c<b, with the stated hypotheses.","Rolle: if additionally f(a)=f(b), then f'(c)=0 somewhere inside.","If f'=0 throughout an interval, f is constant there."],
 examples:[{problem:"Find the MVT point for f(x)=x² on [1,3].",steps:["The secant slope is (9-1)/2=4.","2c=4 gives c=2, which lies inside the interval."]},{problem:"Can Rolle's theorem be applied to |x| on [-1,1]?",steps:["Continuity and equal endpoint values hold.","Differentiability fails at zero, so the theorem cannot be applied."]}],misconception:"A theorem failing to apply does not prove its conclusion is false; it means that theorem supplies no guarantee.",
 questions:[n("c-mvt-1","Find the MVT value c for f(x)=x² on [2,6].","4","Equate tangent and secant slopes.",["Secant slope=(36-4)/4=8; 2c=8 gives c=4."]),n("c-mvt-2","Find the Rolle point for f(x)=x²-4x on [0,4].","2","Endpoint values agree.",["f'=2x-4=0 at c=2."]),pick("c-mvt-3","Can the MVT be applied to f(x)=1/x on [-1,1]?","No: continuity fails",["Yes","No: continuity fails"],"Check the entire closed interval.",["f is undefined at zero."]),pick("c-mvt-4","A smooth trip covers net 120 km in 2 hours. What does the MVT guarantee for the position function?","Velocity equals 60 km/h at some interior time",["Velocity is always 60 km/h","Velocity equals 60 km/h at some interior time","Speed never exceeds 60 km/h"],"Average need not mean constant.",["The average velocity is 60; the theorem guarantees at least one matching instantaneous velocity."]),n("c-mvt-5","Find the MVT point c for f(x)=ln(x) on [1,e].","e-1","The derivative is 1/x.",["The secant slope is 1/(e-1); 1/c=1/(e-1) gives c=e-1 in (1,e)."]),pick("c-mvt-6","If f'(x)=0 for every x in a connected interval, what follows?","f is constant on that interval",["f is zero on that interval","f is constant on that interval","f has no values there"],"A zero rate need not mean a zero height.",["The MVT forces equal function values at any two inputs in the interval."])]})
],[q("c-ext-r1","Find the absolute minimum and maximum values of x² on [-2,1].",[field("Minimum value","0"),field("Maximum value","4")],"Compare the critical point and endpoints.",["The outputs at -2,0,1 are 4,0,1."]),n("c-ext-r2","For f(x)=x³ on [-1,1], how many interior points satisfy the MVT equation?","2","Set 3c² equal to the secant slope.",["Secant slope=1; c=±1/sqrt(3), both interior."]),pick("c-ext-r3","A continuous function on [0,4] has a corner at x=2. Is an absolute maximum still guaranteed?","Yes",["Yes","No"],"The Extreme Value Theorem does not require differentiability.",["Continuity on the closed bounded interval is sufficient."])]);

const applications = chapter("c-applications","Graph Shape & Optimization","Translate derivative signs into behavior and build models to optimize.",[
 section({id:"c-shape",title:"Increasing, Concavity & Curve Sketching",teaches:["derivative-sign-charts","concavity","inflection"],requires:["critical-points","mean-value-theorem","higher-derivatives"],
 paragraphs:["A positive first derivative means the function increases; a negative first derivative means it decreases. Split the domain at critical numbers and discontinuities, then test a point in each interval. A change from positive to negative marks a local maximum; negative to positive marks a local minimum. If the sign does not change, a critical point may be neither. Keep domain breaks separate from points that belong to the curve.","The second derivative describes how slopes change. Positive f'' means increasing slopes and concave up; negative f'' means decreasing slopes and concave down. An inflection point is a point on a continuous curve where concavity changes. Merely finding f''=0 supplies candidates. To sketch a curve coherently, combine domain, intercepts, asymptotes, first-derivative behavior, extrema, and concavity. A second-derivative test can classify a stationary point when f'' is nonzero, but f''=0 is inconclusive."],
 rules:["f'>0: increasing; f'<0: decreasing. Check sign changes at candidates.","f''>0: concave up; f''<0: concave down. An inflection requires a change in concavity.","At f'(c)=0, f''(c)>0 gives a local minimum; f''(c)<0 gives a local maximum."],
 examples:[{problem:"Analyze f(x)=x³-3x.",steps:["f'=3(x-1)(x+1): increasing outside [-1,1], decreasing inside.","Local maximum at x=-1, minimum at 1. f''=6x changes sign at 0, an inflection point."]},{problem:"Does f(x)=x⁴ have an inflection at zero?",steps:["f''=12x² is zero at zero.","It stays positive on both sides, so concavity does not change."]}],misconception:"Increasing and concave up are independent: a function can increase while its positive slopes get smaller.",
 plot:{label:"A cubic with turning points and a change of concavity",xRange:[-2.5,2.5],yRange:[-5,5],curves:[{expression:"x^3-3*x",label:"x³−3x"}]},
 questions:[interval("c-shape-1","For f(x)=x²-4x, give the open interval where f'(x)>0.","(2,inf)","Solve 2x-4>0.",["Positive slope occurs for x>2."]),interval("c-shape-2","For f(x)=x³-3x, give the open interval where f'(x)<0.","(-1,1)","Use the sign of 3(x-1)(x+1).",["The product is negative between its roots."]),q("c-shape-3","For f(x)=x³-3x, give the local maximum and minimum x-locations.",[field("x at local maximum","-1"),field("x at local minimum","1")],"Use derivative sign changes.",["At -1, + becomes -; at 1, - becomes +."]),interval("c-shape-4","For f(x)=x³-6x², give the open interval where f''(x)>0.","(2,inf)","Differentiate twice.",["f''=6x-12>0 when x>2."]),q("c-shape-5","Find the inflection point of f(x)=x³-6x². Give both coordinates.",[field("x","2"),field("y","-16")],"Confirm a concavity change, then evaluate f.",["f'' changes sign at 2; f(2)=8-24=-16."]),pick("c-shape-6","For f(x)=x⁴ at x=0, what does f''(0)=0 prove by itself?","The second-derivative test is inconclusive",["There is an inflection point","There is a maximum","The second-derivative test is inconclusive"],"A zero test value is not a classification.",["Additional sign or value analysis is needed."]),interval("c-shape-7","For f(x)=1/x, give the open interval where it is concave down.","(-inf,0)","Use f''=2/x³ and the domain.",["The second derivative is negative for x<0; zero is not in the curve."]),pick("c-shape-8","On an interval f'>0 and f''<0. Describe the curve.","Increasing with decreasing slopes",["Decreasing with increasing slopes","Increasing with decreasing slopes","Increasing with increasing slopes"],"Separate the meanings of first and second derivatives.",["Values rise, but tangent slopes become smaller."])]}),
 section({id:"c-optimization",title:"Optimization from a Situation",teaches:["optimization"],requires:["absolute-extrema","derivative-sign-charts","functions"],
 paragraphs:["Optimization starts before differentiating. Identify the quantity to maximize or minimize, express the fixed constraints, and reduce the objective to one variable. State the feasible domain: negative lengths or production beyond a stated capacity may be algebraically possible but physically meaningless. The derivative then finds interior candidates, not automatically the answer to the whole situation.","Verify the best candidate using endpoint comparisons or a justified sign argument. Report the requested quantities with units, not just the critical number. A rectangle's maximizing width is different from its maximum area. In an open physical domain, checking behavior near the excluded boundaries may establish that an interior maximum is global. The skill is choosing a model from the story and then using the differentiation tools already learned."],
 rules:["Define objective + constraint + feasible domain before finding critical numbers.","Use the constraint to write a one-variable objective.","Check that the result really gives the requested maximum or minimum."],
 examples:[{problem:"A rectangle has perimeter 40 m. Maximize area.",steps:["If width is x, length is 20-x and area is x(20-x), 0<x<20.","A'=20-2x=0 at x=10; the downward parabola gives maximum area 100 m²."]},{problem:"A farmer has 60 m of fence for three sides of a rectangle along a river.",steps:["If each perpendicular side is x, the third side is 60-2x; A=x(60-2x).", "A'=60-4x=0 at x=15. The third side is 30 m and area is 450 m²."]}],misconception:"A zero derivative of the wrong modeled quantity cannot solve the original optimization problem.",
 questions:[q("c-opt-1","A rectangle has perimeter 48 m. Give the dimensions that maximize area, followed by that area.",[field("Width (m)","12"),field("Length (m)","12"),field("Maximum area (m²)","144")],"Reduce the perimeter constraint to one variable.",["A=x(24-x); A'=24-2x=0 at 12. Both sides are 12 and area is 144."]),q("c-opt-2","A farmer uses 80 m of fence for three sides of a rectangle; the river is the fourth side. Give each perpendicular side and the side parallel to the river at maximum area.",[field("Perpendicular side (m)","20"),field("Parallel side (m)","40")],"Two copies of the perpendicular side use fencing.",["A=x(80-2x); A'=80-4x=0 at 20, leaving 40."]),e("c-opt-3","Squares of side x cm are cut from all four corners of a 12 cm by 18 cm sheet; folding makes an open box. Give its volume expression in x for 0<x<6.","x*(12-2*x)*(18-2*x)","Each base dimension loses two cutout lengths.",["Height x, width 12-2x, length 18-2x; multiply the three."]),n("c-opt-4","A positive rectangle has area 36 m². Find the width that minimizes its perimeter.","6","Use length 36/x.",["P=2x+72/x; P'=2-72/x²=0 gives x=6. The derivative goes from negative to positive."]),n("c-opt-5","Revenue is R(x)=40x-x² dollars and cost is C(x)=10x+20 dollars for 0≤x≤30 units. What production x maximizes profit?","15","Profit is revenue minus cost.",["P=30x-x²-20; P'=30-2x=0 at 15. This is the vertex of a downward parabola in the domain."]),n("c-opt-6","The sum of two nonnegative numbers is 20. What is their maximum product?","100","Model the product using one number.",["P=x(20-x) on [0,20]. It is maximized at x=10, giving 100."]),n("c-opt-7","A 12 cm square sheet becomes an open box by cutting equal corner squares of side x, 0<x<6. Find the cut size that maximizes volume.","2","Differentiate x(12-2x)² and consider the physical interval.",["V'=(12-2x)(12-6x). The interior critical point is x=2; V increases then decreases, while boundary volume approaches zero."])]})
],[q("c-app-r1","For f(x)=x³-12x, give the local maximum x-location and the inflection x-location.",[field("Local maximum x","-2"),field("Inflection x","0")],"Use different derivatives for the two questions.",["f'=3(x-2)(x+2) changes + to - at -2. f''=6x changes sign at 0."]),n("c-app-r2","A rectangle along a wall needs fencing on only three sides. With 100 m of fence, what is the maximum area in m²?","1250","Let x be a side perpendicular to the wall.",["A=x(100-2x), maximized at x=25; the third side is 50, giving 1250."]),pick("c-app-r3","A curve has f'(2)=0, with f'<0 just left of 2 and f'>0 just right. What occurs at 2?","Local minimum",["Local maximum","Local minimum","No extremum"],"Use the direction of the turn.",["The curve changes from decreasing to increasing."])]);

const primitives = chapter("c-antiderivatives","Antiderivatives & Motion","Reverse differentiation and recover a quantity from its rate.",[
 section({id:"c-primitives",title:"Families of Antiderivatives",teaches:["antiderivatives","initial-value-problems"],requires:["power-rule","trig-derivatives","exp-log-derivatives"],
 paragraphs:["An antiderivative of f is a function F whose derivative is f. Reversing the power rule gives x^(n+1)/(n+1) for x^n when n≠-1. The exponent -1 is exceptional: an antiderivative of 1/x is ln|x| on an interval not crossing zero. Differentiation erases constants, so F+C is a whole family with the same derivative. The notation ∫f(x) dx denotes this family of indefinite integrals.","Known derivative formulas also run backward: e^x stays e^x, cosine integrates to sine, and sine integrates to negative cosine. Check an unfamiliar candidate by differentiating it. An initial value such as F(0)=3 chooses one constant from the family. The answer field will explicitly request either the nonconstant part with +C omitted or the unique function satisfying the initial value; worked solutions still show where the constant belongs."],
 rules:["∫x^n dx=x^(n+1)/(n+1)+C for n≠-1; ∫1/x dx=ln|x|+C.","∫e^x dx=e^x+C; ∫cos(x) dx=sin(x)+C; ∫sin(x) dx=-cos(x)+C.","∫sec(x)^2 dx=tan(x)+C; ∫1/(1+x²) dx=atan(x)+C; ∫1/sqrt(1-x²) dx=asin(x)+C."],
 examples:[{problem:"Find the family of antiderivatives of 6x²-4.",steps:["Increase each power and divide by its new exponent.","F(x)=2x³-4x+C. Differentiating returns 6x²-4."]},{problem:"F'(x)=2x and F(1)=5. Find F.",steps:["F=x²+C.","5=1+C gives C=4, so F=x²+4."]}],misconception:"A particular antiderivative is not the whole family; initial information is needed to determine the constant.",
 questions:[e("c-anti-1","Find the nonconstant part of ∫4x³ dx. Omit +C.","x^4","Reverse the power rule.",["∫4x³ dx=x⁴+C."]),e("c-anti-2","Find the nonconstant part of ∫(3x²-2x+5) dx. Omit +C.","x^3-x^2+5*x","Integrate each term.",["x³-x²+5x+C differentiates to the integrand."]),fn("c-anti-3","Find the nonconstant part of ∫x^(-2) dx for x>0. Omit +C.","-1/x","The new exponent is -1.",["x^(-1)/(-1)+C=-1/x+C."]),fn("c-anti-4","Find the nonconstant part of ∫1/x dx for x>0. Omit +C.","ln(x)","Do not divide by a new exponent of zero.",["The logarithm is the exceptional power-rule case."]),fn("c-anti-5","Find the nonconstant part of ∫(2e^x+3sin(x)) dx. Omit +C.","2*exp(x)-3*cos(x)","Check the sine term's sign by differentiating.",["2e^x-3cos(x)+C has derivative 2e^x+3sin(x)."]),e("c-anti-6","F'(x)=3x² and F(2)=10. Give F(x).","x^3+2","Use the initial value to determine C.",["F=x³+C; 10=8+C gives C=2."]),fn("c-anti-7","F'(x)=cos(x) and F(0)=-2. Give F(x).","sin(x)-2","The integration constant does not have to be zero.",["F=sin(x)+C and C=-2."]),pick("c-anti-8","On one interval F'=G'. What can you conclude about F-G?","It is constant",["It is necessarily zero","It is constant","It equals x"],"Differentiate their difference.",["Its derivative is zero, so the MVT implies it is constant on the interval."])]}),
 section({id:"c-motion",title:"Recovering Position & Tracking Direction",teaches:["motion-antiderivatives"],requires:["antiderivatives","derivative-sign-charts"],
 paragraphs:["Velocity is the derivative of position, and acceleration is the derivative of velocity. Recovering position from acceleration therefore requires two integrations and two pieces of initial information. Each integration introduces its own constant. Keep position units, velocity units, and acceleration units distinct: the symbols represent related quantities, not interchangeable formulas.","Displacement is final position minus initial position. Total distance is different when direction changes: locate the times where velocity changes sign, compute position changes on the resulting intervals, and add their magnitudes. Speed is the magnitude of velocity. A negative velocity means motion in the negative direction, not negative distance traveled. The later definite-integral method will package this same accumulation reasoning."],
 rules:["s'=v and v'=a. One initial value is needed for each integration constant.","Displacement on [a,b] is s(b)-s(a).","For total distance, split at direction changes and add absolute position changes."],
 examples:[{problem:"a(t)=6, v(0)=2, s(0)=1. Recover velocity and position.",steps:["v(t)=6t+C; v(0)=2 gives v=6t+2.","s(t)=3t²+2t+D; s(0)=1 gives s=3t²+2t+1."]},{problem:"s(t)=t²-4t on 0≤t≤4. Find displacement and distance.",steps:["v=2t-4 changes sign at t=2. Positions are 0,-4,0.","Displacement is 0; distance is 4+4=8."]}],misconception:"Integrating acceleration once gives velocity, not position; the first constant cannot replace the second one.",
 questions:[n("c-motion-1","v(t)=3t² m/s and s(0)=5 m. Find s(2) in meters.","13","Integrate velocity and use the position condition.",["s=t³+5, so s(2)=13."]),n("c-motion-2","a(t)=4 m/s², v(0)=-1 m/s, s(0)=2 m. Find s(3) in meters.","17","Integrate twice.",["v=4t-1; s=2t²-t+2; s(3)=18-3+2=17."]),n("c-motion-3","s(t)=t²-6t meters on [0,6] seconds. Find displacement.","0","Subtract endpoint positions.",["s(6)=0=s(0), so net displacement is zero."]),n("c-motion-4","s(t)=t²-6t meters on [0,6] seconds. Find total distance.","18","Split at the direction change.",["v=2t-6 changes sign at 3; s(3)=-9. Distance is 9+9=18."]),n("c-motion-5","v(t)=t-2 m/s. What is speed at t=0?","2","Speed is a magnitude.",["|v(0)|=|-2|=2 m/s."]),n("c-motion-6","A particle has v(t)=2t-2 and starts at s(0)=3. Find its minimum position on 0≤t≤3.","2","Find when velocity changes from negative to positive.",["s=t²-2t+3 is least at t=1, where s=2; endpoints give 3 and 6."])]})
],[fn("c-anti-r1","F'(x)=e^x+2x and F(0)=4. Give F(x).","exp(x)+x^2+3","Find the family, then use the value at zero.",["F=e^x+x²+C and 1+C=4, so C=3."]),n("c-anti-r2","s(t)=t²-2t on [0,3]. Find total distance traveled.","5","The turning time is t=1.",["Positions at 0,1,3 are 0,-1,3. Distance is 1+4=5."]),fn("c-anti-r3","Find the nonconstant part of ∫(cos(x)+1/(1+x²)) dx. Omit +C.","sin(x)+atan(x)","Use two known reverse derivative rules.",["The family is sin(x)+atan(x)+C."])]);

const accumulation = chapter("c-accumulation","Riemann Sums & Definite Integrals","Build accumulation from small signed contributions before using a shortcut.",[
 section({id:"c-riemann",title:"Rectangles, Sums & Numerical Estimates",teaches:["riemann-sums","numerical-integration"],requires:["calculus-change","limit-laws"],
 paragraphs:["A varying rate contributes approximately rate times duration over a short time interval. Divide [a,b] into n equal pieces of width Δx=(b-a)/n and add f(sample point)*Δx. This is a Riemann sum. Left, right, and midpoint sums choose different sample inputs within each piece. Heights can be negative, so these sums represent signed accumulation rather than necessarily ordinary geometric area.","More and narrower pieces can improve an estimate, but a finite sum is not generally the exact accumulation. For an increasing function, a left sum underestimates the integral and a right sum overestimates it. Midpoint estimates use the middle of each interval. Averaging corresponding left and right sums gives the trapezoidal estimate. The limit as the largest width approaches zero, when it exists independently of sample choices, defines the definite integral."],
 rules:["Δx=(b-a)/n; left inputs a,a+Δx,...,b-Δx; right inputs a+Δx,...,b.","Midpoint inputs are a+Δx/2,a+3Δx/2,...,b-Δx/2.","For equal widths T_n=(L_n+R_n)/2. Σ means add the listed terms; Σi=n(n+1)/2 and Σi²=n(n+1)(2n+1)/6 for i=1,...,n."],
 examples:[{problem:"Estimate accumulation of f(x)=x² on [0,2] with two right rectangles.",steps:["Δx=1; right inputs are 1 and 2.","R₂=(1²+2²)·1=5."]},{problem:"Use two midpoint rectangles for the same function and interval.",steps:["Midpoints are 0.5 and 1.5.","M₂=(0.25+2.25)·1=2.5."]},{problem:"Use n right rectangles for f(x)=x on [0,1], then take the limit.",steps:["Width is 1/n, right heights i/n, so R_n=Σi/n²=(n+1)/(2n).", "As n→∞, R_n→1/2, the triangular area."]}],misconception:"Adding sampled heights without multiplying by interval width produces the wrong quantity and units.",
 questions:[n("c-sum-1","For [1,5] split into 8 equal pieces, find Δx.","1/2","Divide interval length by piece count.",["(5-1)/8=1/2."]),n("c-sum-2","Find L₂ for f(x)=x² on [0,2].","1","Use left inputs 0 and 1, each with width 1.",["(0²+1²)·1=1."]),n("c-sum-3","Find R₂ for f(x)=x² on [1,3].","13","The right inputs are 2 and 3.",["(4+9)·1=13."]),n("c-sum-4","Find M₂ for f(x)=2x+1 on [0,4].","20","Width is 2 and midpoints are 1 and 3.",["[f(1)+f(3)]·2=(3+7)·2=20."]),n("c-sum-5","Flow rates at t=0,2,4 minutes are 3,5,4 L/min. Estimate volume added using two left rectangles on [0,4].","16","Use rates at the start of each 2-minute interval.",["(3+5)·2=16 L."]),n("c-sum-6","For a given equal partition, L_n=12 and R_n=18. Find the trapezoidal estimate.","15","Average the corresponding estimates.",["(12+18)/2=15."]),pick("c-sum-7","For a strictly increasing continuous function, how does its left sum compare with its definite integral?","It underestimates",["It underestimates","It overestimates","It is always exact"],"Compare each rectangle height to the curve on its interval.",["Every left height is below subsequent heights in its piece."]),n("c-sum-8","A sequence of right sums simplifies to (n+1)(2n+1)/(6n²). Find its limit as n→∞.","1/3","Compare leading terms or divide by n².",["The limit is 2/6=1/3."])]}),
 section({id:"c-definite",title:"Signed Area & Integral Properties",teaches:["definite-integrals","integral-properties"],requires:["riemann-sums","antiderivatives"],
 paragraphs:["The definite integral ∫ from a to b of f(x) dx is the limit of its Riemann sums, and its result is a number. For a continuous function it exists. Regions above the horizontal axis contribute positively; regions below contribute negatively. Ordinary total area counts both as positive and may require splitting at zeros. The variable x inside the integral is a dummy variable; changing its name to t does not change the number.","Integral properties follow from adding the underlying pieces. Splitting the interval adds the accumulations, reversing bounds reverses the sign, and equal bounds give zero. Constants can be taken outside, and sums of integrands can be integrated term by term. These facts let you calculate new integrals from known ones without finding any antiderivative. The next chapter explains why antiderivatives provide an efficient way to compute them."],
 rules:["∫_a^b f = -∫_b^a f; ∫_a^a f=0; ∫_a^c f=∫_a^b f+∫_b^c f.","∫(af+bg)=a∫f+b∫g with common bounds.","For nonnegative f, the integral is area. Total area for changing sign uses |f|."],
 examples:[{problem:"Find ∫_0^3 2 dx by geometry.",steps:["A rectangle has width 3 and height 2.","The signed area is 6."]},{problem:"A curve encloses area 5 above and area 2 below the axis on [a,b].",steps:["The definite integral is 5-2=3.","The total geometric area is 5+2=7."]}],misconception:"A zero integral can mean cancellation, not that the function is zero everywhere.",
 questions:[n("c-intprop-1","Evaluate ∫_1^5 3 dx geometrically.","12","Use rectangle width 4.",["3(5-1)=12."]),n("c-intprop-2","Evaluate ∫_0^4 x dx geometrically.","8","Use a triangle.",["Base 4, height 4: area (1/2)·4·4=8."]),q("c-intprop-3","On [a,b], a curve has area 8 above the axis and 3 below. Give its signed integral and total area.",[field("Signed integral","5"),field("Total area","11")],"Use subtraction versus addition.",["Signed accumulation is 8-3=5; total area is 8+3=11."]),n("c-intprop-4","Given ∫_0^2 f=7 and ∫_2^5 f=-3, find ∫_0^5 f.","4","Add neighboring intervals.",["7+(-3)=4."]),n("c-intprop-5","Given ∫_1^4 f=6, find ∫_4^1 2f.","-12","Account for both reversed bounds and the constant.",["2(-6)=-12."]),n("c-intprop-6","On the same bounds, ∫f=4 and ∫g=3. Find ∫(2f-g).","5","Use linearity.",["2(4)-3=5."]),n("c-intprop-7","Evaluate ∫_2^2 e^(x²) dx.","0","The interval has no width.",["Equal bounds make any continuous integrand's integral zero."])]})
],[n("c-acc-r1","Find M₂ for f(x)=x² on [0,4].","20","Use width 2 and midpoints 1,3.",["2(1+9)=20."]),n("c-acc-r2","Given ∫_0^5 f=9 and ∫_0^2 f=4, find ∫_5^2 f.","-5","First isolate [2,5], then reverse.",["∫_2^5 f=5, hence ∫_5^2 f=-5."]),q("c-acc-r3","A constant velocity -3 m/s lasts 4 seconds. Give displacement and total distance.",[field("Displacement (m)","-12"),field("Distance (m)","12")],"Signed motion and distance differ.",["Displacement is -3·4=-12; distance is its magnitude, 12."])]);

const fundamental = chapter("c-ftc","The Fundamental Theorem of Calculus","Connect the rate of accumulation with antiderivatives.",[
 section({id:"c-accumulation-functions",title:"Accumulation Functions & Their Derivatives",teaches:["ftc-derivative"],requires:["definite-integrals","chain-rule","continuity"],
 paragraphs:["Let A(x)=∫_a^x f(t) dt. Here the upper endpoint moves, so A is a function, not a single fixed number. Increasing x by a tiny amount adds a thin slice whose accumulation is approximately f(x) times the width. The Fundamental Theorem says A'(x)=f(x) when f is continuous. Differentiating accumulation recovers the current rate even when an elementary antiderivative is unavailable.","A changing upper bound such as x² adds a chain rule: the endpoint's speed multiplies the integrand evaluated at that endpoint. A moving lower bound contributes with a negative sign because raising it removes accumulation. With two moving bounds, take the upper contribution minus the lower contribution. The dummy variable t disappears only after you substitute the actual endpoint expressions."],
 rules:["d/dx ∫_a^x f(t)dt=f(x) for continuous f.","d/dx ∫_a^g(x) f(t)dt=f(g(x))*g'(x).","d/dx ∫_h(x)^g(x) f(t)dt=f(g(x))*g'(x)-f(h(x))*h'(x)."],
 examples:[{problem:"Differentiate A(x)=∫_1^x sqrt(1+t²) dt.",steps:["The integrand is continuous.","A'(x)=sqrt(1+x²); no antiderivative calculation is needed."]},{problem:"Differentiate B(x)=∫_0^(x²) cos(t) dt.",steps:["Evaluate the integrand at x² and multiply by its endpoint derivative.","B'(x)=2x cos(x²)."]}],misconception:"The derivative is the integrand evaluated at the moving endpoint, not the derivative of the integrand.",
 questions:[e("c-ftcd-1","A(x)=∫_2^x (t²+1) dt. Give A'(x).","x^2+1","Use the accumulation form of the theorem.",["Replace the dummy input t by x."]),fn("c-ftcd-2","A(x)=∫_0^x e^(t²) dt. Give A'(x).","exp(x^2)","An explicit elementary antiderivative is not required.",["Continuity gives A'(x)=e^(x²)."]),fn("c-ftcd-3","A(x)=∫_0^(3x) sin(t) dt. Give A'(x).","3*sin(3*x)","Include the moving endpoint's rate.",["sin(3x)·3."]),e("c-ftcd-4","A(x)=∫_x^4 t² dt. Give A'(x).","-x^2","Increasing the lower bound removes area.",["Reverse the bounds or use the negative lower-end contribution."]),e("c-ftcd-5","A(x)=∫_x^(x²) (t+1) dt. Give A'(x).","2*x*(x^2+1)-(x+1)","Both endpoints move.",["Upper contribution: (x²+1)2x. Lower contribution: -(x+1)."]),n("c-ftcd-6","A(x)=∫_0^x (t²-4) dt. Find A'(1).","-3","Evaluate the integrand, not its derivative.",["A'(1)=1²-4=-3."]),interval("c-ftcd-7","A(x)=∫_0^x (t-3) dt. Give the open interval where A'(x)>0.","(3,inf)","The accumulated function's derivative is x-3.",["x-3>0 when x>3."])]}),
 section({id:"c-evaluate-integrals",title:"Evaluating Integrals, Net Change & Average Value",teaches:["ftc-evaluation","integral-average","net-change"],requires:["ftc-derivative","antiderivatives","motion-antiderivatives"],
 paragraphs:["If F is an antiderivative of continuous f on [a,b], the Fundamental Theorem gives ∫_a^b f(x) dx=F(b)-F(a). The order is upper minus lower; parentheses around the entire lower evaluation prevent sign errors. Any additive constant cancels, so a definite integral's final numerical answer does not include +C. This theorem turns the limiting-sum definition into an efficient evaluation method.","Integrating a rate gives net change. Add the initial amount to recover the final amount, and split sign changes when total distance or total area is requested. The average value of f over [a,b] is its integral divided by b-a: the constant height giving the same signed accumulation. It is not generally the average of the two endpoint values. If f is continuous, it equals some actual function value in the interval."],
 rules:["∫_a^b f(x)dx=F(b)-F(a) when F'=f and f is continuous on [a,b].","Final quantity = initial quantity + integral of its rate.","Average value = (1/(b-a))∫_a^b f; total distance = ∫_a^b |v|."],
 examples:[{problem:"Evaluate ∫_1^3 2x dx.",steps:["An antiderivative is x².","F(3)-F(1)=9-1=8."]},{problem:"Find the average value of x² on [0,3].",steps:["Its integral is [x³/3]_0^3=9.","Divide by interval length 3 to get average value 3, not endpoint average 4.5."]},{problem:"A tank starts with 10 L; net inflow is 2t L/min for 0≤t≤3.",steps:["Added water is ∫_0^3 2t dt=9 L.","Final amount is 10+9=19 L."]}],misconception:"F(b)-F(a) computes net signed accumulation; taking an absolute value only at the end does not give total area when signs change.",
 questions:[n("c-ftce-1","Evaluate ∫_0^2 3x² dx.","8","Use an antiderivative and endpoint subtraction.",["[x³]_0^2=8."]),n("c-ftce-2","Evaluate ∫_1^3 (2x-4) dx.","0","Keep the entire lower-end expression grouped.",["[x²-4x]_1^3=(-3)-(-3)=0."]),n("c-ftce-3","Evaluate ∫_0^pi sin(x) dx.","2","The antiderivative is -cos(x).",["-cos(pi)-(-cos(0))=1+1=2."]),n("c-ftce-4","Evaluate ∫_1^e 1/x dx.","1","The interval stays positive.",["[ln x]_1^e=1-0=1."]),n("c-ftce-5","Find the average value of x² on [0,2].","4/3","Divide its integral by the interval length.",["Integral=8/3; average=(8/3)/2=4/3."]),n("c-ftce-6","A tank starts with 20 L and has net flow 3t²-2 L/min over 0≤t≤2. Find its final volume.","24","The integral gives a change, not the final total.",["Change=[t³-2t]_0^2=4 L; final volume is 24 L."]),n("c-ftce-7","Find the total area between y=x-1 and the x-axis on [0,3].","5/2","Split at x=1, where the sign changes.",["The two triangular areas are 1/2 and 2; total is 5/2."]),n("c-ftce-8","Find the total distance traveled when v(t)=2t-2 on [0,3].","5","Integrate speed by splitting at t=1.",["Displacements are -1 on [0,1] and 4 on [1,3]; distance is 1+4=5."])]})
],[fn("c-ftc-r1","Differentiate A(x)=∫_1^(x²) e^t dt.","2*x*exp(x^2)","Evaluate the integrand at the endpoint and multiply by its rate.",["e^(x²)·2x."]),n("c-ftc-r2","Find the average value of 3x²+1 on [0,2].","5","Compute the integral then divide by 2.",["[x³+x]_0^2=10; average=5."]),n("c-ftc-r3","A population starts at 100 and changes at rate 4e^t per year. Find its size at t=1.","96+4*e","Add the initial size to the net change.",["100+∫_0^1 4e^t dt=100+4(e-1)=96+4e."])]);

const substitution = chapter("c-substitution","Substitution & Calculus Synthesis","Recognize a reverse chain rule and choose a method from the mathematical structure.",[
 section({id:"c-indefinite-sub",title:"Substitution as a Reverse Chain Rule",teaches:["indefinite-substitution"],requires:["chain-rule","antiderivatives","ftc-evaluation"],
 paragraphs:["Substitution reverses the chain rule. If an integrand contains a function of g(x) multiplied by g'(x), let u=g(x), so du=g'(x)dx. The integral becomes a simpler one in u. A constant mismatch can be adjusted by multiplying outside the integral; a remaining nonconstant factor cannot simply be discarded. Choose the substitution because of the whole integrand, not merely because a nested expression is visible.","After an indefinite integration, replace u by its original expression and include an arbitrary constant in the mathematical family. In typed practice the prompt asks for the nonconstant part with +C omitted. Verify the result by differentiation: an extra factor in the derivative usually means a missing reciprocal constant in the antiderivative. Quotients containing a denominator and its derivative often lead to ln|u|; the real domain determines when ln(u) alone is appropriate."],
 rules:["∫f(g(x))g'(x)dx = F(g(x))+C when F'=f.","If u=g(x), every changing factor must be accounted for in du or rewritten in u.","∫g'(x)/g(x)dx=ln|g(x)|+C on an interval where g≠0."],
 examples:[{problem:"Find ∫2x(x²+1)^3 dx.",steps:["Let u=x²+1, du=2x dx.","∫u³du=u⁴/4+C=(x²+1)^4/4+C."]},{problem:"Find ∫cos(3x) dx.",steps:["Let u=3x, so dx=du/3.","The result is sin(3x)/3+C, confirmed by differentiation."]},{problem:"Find ∫x/(x²+4) dx.",steps:["The denominator's derivative is 2x, twice the numerator.","The result is (1/2)ln(x²+4)+C; its argument is positive for every real x."]}],misconception:"Substitution is not permission to drop factors that are inconvenient to rewrite.",
 questions:[fn("c-sub-1","Find the nonconstant part of ∫6x(x²+2)^2 dx. Omit +C.","(x^2+2)^3","The inner derivative is 2x.",["With u=x²+2, the integral is 3∫u²du=u³+C."]),fn("c-sub-2","Find the nonconstant part of ∫e^(4x) dx. Omit +C.","exp(4*x)/4","Compensate for the inner rate 4.",["(1/4)e^(4x)+C differentiates to e^(4x)."]),fn("c-sub-3","Find the nonconstant part of ∫sin(2x) dx. Omit +C.","-cos(2*x)/2","Both sign and scaling matter.",["-(1/2)cos(2x)+C."]),fn("c-sub-4","Find the nonconstant part of ∫2x/(x²+5) dx. Omit +C.","ln(x^2+5)","Recognize the derivative of the denominator.",["u=x²+5 leads to ∫du/u=ln(u)+C; u>0."]),fn("c-sub-5","Find the nonconstant part of ∫x/sqrt(x²+1) dx. Omit +C.","sqrt(x^2+1)","Use u=x²+1 and retain the factor 1/2.",["(1/2)∫u^(-1/2)du=sqrt(u)+C."]),fn("c-sub-6","Find the nonconstant part of ∫cos(x)/(1+sin(x)^2) dx. Omit +C.","atan(sin(x))","The numerator is the derivative of the nested sine.",["u=sin(x), du=cos(x)dx; ∫du/(1+u²)=atan(u)+C."]),fn("c-sub-7","Find the nonconstant part of ∫ln(x)/x dx for x>0. Omit +C.","ln(x)^2/2","Use the log as the new variable.",["u=ln(x), du=dx/x; ∫u du=u²/2+C."]),fn("c-sub-8","Find the nonconstant part of ∫x e^(x²) dx. Omit +C.","exp(x^2)/2","The differential supplies twice the numerator.",["u=x² gives (1/2)∫e^u du=e^(x²)/2+C."])]}),
 section({id:"c-definite-sub",title:"Changed Bounds & Mixed Applications",teaches:["definite-substitution","calculus-synthesis"],requires:["indefinite-substitution","net-change","optimization","integral-average"],
 paragraphs:["For a definite integral, changing variables also changes the bounds. If u=g(x), evaluate g at both original endpoints and use those u-values as the new limits. After integration in u, evaluate at the u-bounds; do not mix an antiderivative in u with endpoints that still represent x. Alternatively, return to x first and use the original bounds. Both complete routes are valid.","A decreasing substitution may reverse bound order; the sign carried by du must be kept as well. In mixed problems, first decide what is being requested: a derivative gives a local rate, an integral gives accumulation, an initial value turns change into a final amount, and optimization requires a model with feasible inputs. Not every elementary-looking integral has an elementary antiderivative, and substitution is not a universal method. A Riemann-sum estimate remains available when exact techniques do not fit."],
 rules:["∫_a^b f(g(x))g'(x)dx = ∫_g(a)^g(b) f(u)du.","Use u-bounds with a u-antiderivative, or x-bounds after substituting back.","Choose the operation from the requested quantity: rate, accumulation, average, or extremum."],
 examples:[{problem:"Evaluate ∫_0^1 2x(x²+1)^2 dx.",steps:["u=x²+1 changes bounds 0,1 to 1,2.","∫_1^2 u²du=[u³/3]_1^2=7/3."]},{problem:"Evaluate ∫_0^1 e^(-x) dx.",steps:["u=-x changes bounds to 0,-1 and dx=-du.","-∫_0^(-1)e^u du=1-e^(-1)."]}],misconception:"Changing the variable without changing or later restoring the bounds mixes two different inputs.",
 questions:[n("c-dsub-1","Evaluate ∫_0^2 2x(x²+1) dx.","12","Use bounds 1 and 5 after substitution.",["∫_1^5 u du=(25-1)/2=12."]),n("c-dsub-2","Evaluate ∫_0^1 3e^(3x) dx.","e^3-1","The inner derivative is already present.",["The antiderivative is e^(3x), giving e³-1."]),n("c-dsub-3","Evaluate ∫_0^(pi/2) sin(x)cos(x) dx.","1/2","Let u=sin(x), with bounds 0 and 1.",["∫_0^1 u du=1/2."]),n("c-dsub-4","Evaluate ∫_0^1 x/(x²+1) dx.","ln(2)/2","Account for the missing factor 2.",["(1/2)∫_1^2 du/u=(1/2)ln(2)."]),n("c-dsub-5","Evaluate ∫_0^2 (3-x)^2 dx using any valid method.","26/3","Expansion and substitution are both valid.",["With u=3-x, the bounds go from 3 to 1 and dx=-du. ∫_1^3 u²du=26/3."]),n("c-dsub-6","Find the average value of 2x e^(x²) on [0,1].","e-1","The interval has length 1; find the accumulation.",["u=x² gives ∫_0^1 e^u du=e-1, which is also the average here."]),n("c-dsub-7","A tank starts with 7 L and has net inflow 4t/(t²+1) L/min on [0,1]. Find the final volume.","7+2*ln(2)","The integral gives the amount added.",["Added volume=2ln(t²+1) from 0 to 1 =2ln2. Add 7."]),pick("c-dsub-8","For ∫e^(x²) dx, a learner sets u=x² and drops dx to claim e^(x²)+C. What is wrong?","The required 2x factor is missing",["The required 2x factor is missing","The method is correct","Every exponential integral is a logarithm"],"Differentiate the claimed result.",["Its derivative is 2x e^(x²), not e^(x²). A substitution must account for all factors."])]})
],[n("c-sub-r1","Evaluate ∫_0^1 4x(x²+1)^3 dx.","15/2","The transformed integral is 2∫_1^2 u³du.",["[u⁴/2]_1^2=(16-1)/2=15/2."]),fn("c-sub-r2","Find the nonconstant part of ∫cos(x)e^(sin(x)) dx. Omit +C.","exp(sin(x))","Use the changing exponent as the new variable.",["u=sin(x), du=cos(x)dx; the result is e^(sin(x))+C."]),q("c-sub-r3","A quantity starts at Q(0)=5 and has Q'(t)=2t for 0≤t≤3. Give Q(3) and its instantaneous rate at t=3.",[field("Q(3)","14"),field("Q'(3)","6")],"Accumulation and the current rate are different questions.",["Q(3)=5+∫_0^3 2t dt=14. The current rate is 2·3=6."])]);

const approaching = chapter("c-approaching","Change & the Meaning of a Limit","Build the bridge from function values to nearby behavior and instantaneous change.",[
  section({id:"c-change",title:"Functions, Units & Average Change",teaches:["calculus-change"],requires:["functions","average-rate"],
    paragraphs:["Calculus asks how quantities change and how small contributions accumulate. A function is a model connecting an input to an output: position to time, cost to production, or population to elapsed years. Before calculating, identify the input, the output, their units, and the domain where the model makes sense. A physically meaningful restriction can be narrower than the algebraic domain.","Over an interval, average rate of change is output change divided by input change. On a graph this is a secant slope joining two distinct points. It measures net change, not the entire journey: a moving object can return to its starting position and have zero average velocity without standing still. Keep parentheses around both differences, particularly when endpoints or outputs are negative."],
    rules:["Average rate on [a,b] = (f(b)-f(a))/(b-a), with a≠b.","Units of a rate = output units / input units.","Average velocity uses displacement, not total distance traveled."],
    examples:[{problem:"Position s(t)=t^2+2t meters. Find average velocity from t=1 to t=3 seconds.",steps:["s(1)=3 and s(3)=15.","(15-3)/(3-1)=6 meters per second."]},{problem:"A tank holds 30 liters at 2 minutes and 18 liters at 5 minutes.",steps:["The change is 18-30=-12 liters over 3 minutes.","Average rate is -4 liters per minute: the tank is losing water."]}],
    misconception:"A rate is not the final output divided by the final input unless the initial point is actually (0,0).",
    questions:[n("c-change-1","For f(x)=x^2, find average rate on [1,4].","5","Compare both endpoint outputs.",["(16-1)/(4-1)=5."]),n("c-change-2","For f(x)=x^2, find average rate on [-3,3].","0","Equal endpoint heights can enclose changing values.",["Both outputs are 9, so the net change is zero."]),n("c-change-3","A culture grows from 120 cells at hour 2 to 300 cells at hour 8. Find its average growth in cells/hour.","30","Divide growth by elapsed time.",["(300-120)/(8-2)=180/6=30."]),n("c-change-4","Position is s(t)=t^2-4t meters. Find average velocity from t=0 to t=3.","-1","Calculate displacement, with its sign.",["s(0)=0, s(3)=-3; -3/3=-1 m/s."]),pick("c-change-5","Temperature is measured in degrees Celsius and time in minutes. What are the units of its rate of change?","degrees Celsius per minute",["degrees Celsius","minutes per degree Celsius","degrees Celsius per minute"],"Output units are divided by input units.",["A temperature change per elapsed time has units °C/min."]),n("c-change-6","C(x)=40+3x is cost in dollars for x items. Find the average cost change per additional item from x=10 to x=25.","3","The fixed charge cancels from the difference.",["(115-70)/(25-10)=3 dollars/item."])]}),
  section({id:"c-limit-meaning",title:"Approach, One-Sided Limits & Missing Values",teaches:["limits-one-sided"],requires:["calculus-change","limit-ideas","piecewise-functions"],
    paragraphs:["The statement lim as x approaches a of f(x)=L describes outputs for inputs close to a, not necessarily the output at a itself. A missing value, a filled dot at another height, or an undefined formula at a need not prevent a limit. Examine the behavior on the punctured neighborhood: x is close to a but different from a.","A left-hand limit uses x<a; a right-hand limit uses x>a. A finite two-sided limit exists only when both sides approach the same finite number. If the sides disagree, the two-sided limit does not exist. Tables and graphs suggest a limit, but a few sampled values do not prove a statement about all nearby inputs; use the formula or stated behavior when available."],
    rules:["lim x→a f(x)=L requires both one-sided limits to equal L.","The value f(a) and the limit at a are separate questions.","DNE means no two-sided limit exists; it is not a numerical value."],
    examples:[{problem:"f(x)=x+2 for x≠1 and f(1)=9. Find the limit and the value at 1.",steps:["Nearby outputs follow x+2, approaching 3 from both sides.","The limit is 3, although f(1)=9."]},{problem:"g(x)=2x for x<2 and g(x)=x+3 for x≥2.",steps:["From the left, outputs approach 4; from the right, 5.","The unequal sides mean the two-sided limit does not exist."]}],
    misconception:"Substituting a into an isolated definition f(a) does not determine the nearby limit.",
    questions:[q("c-limit-1","f(x)=x^2 for x≠2 and f(2)=7. Give lim x→2 f(x) and f(2).",[field("Limit","4"),field("f(2)","7")],"Separate the nearby rule from the point value.",["Nearby x^2 approaches 4; the isolated definition gives 7."]),q("c-limit-2","f(x)=3-x for x<1 and f(x)=x+4 for x≥1. Give the left and right limits at 1.",[field("Left limit","2"),field("Right limit","5")],"Use the formula on the appropriate side.",["3-1=2 on the left; 1+4=5 on the right."]),pick("c-limit-3","The left limit of f at 3 is 4 and the right limit is -4. What is its two-sided limit?","DNE",["0","4","-4","DNE"],"Both sides must agree.",["4≠-4, so there is no two-sided limit."]),n("c-limit-4","For x≠0, f(x)=sin(x)/x. It is given that both one-sided limits at 0 equal 1. What is the two-sided limit?","1","Use the stated agreement, not substitution of 0/0.",["Both sides tend to 1, hence the limit is 1."]),n("c-limit-5","For x<5, g(x)=2x-1. Its value and all values for x≥5 are unspecified. Find lim x→5 from the left g(x).","9","Only the left-hand rule matters.",["2(5)-1=9."]),pick("c-limit-6","A table gives five outputs close to 2 near x=0, but no formula or error bound. What can it establish?","Evidence suggesting a limit of 2",["A proof that the limit is 2","Evidence suggesting a limit of 2","A proof that f(0)=2"],"Finite samples do not control every nearby input.",["The table suggests behavior, not a proof or the point value."]) ]})
],[n("c-approach-r1","s(t)=2t^2-3t meters. Find average velocity on [1,4].","7","Evaluate both times.",["s(1)=-1 and s(4)=20; 21/3=7 m/s."]),q("c-approach-r2","f(x)=x+5 for x≠-1 and f(-1)=8. Give the limit at -1 and the value there.",[field("Limit","4"),field("Value","8")],"A point redefinition need not change a limit.",["Nearby values approach 4; the actual value is 8."]),pick("c-approach-r3","f(x) approaches 6 from the left of 2 and 6 from the right, but is undefined at 2. Its limit is:","6",["6","0","DNE"],"A missing point is allowed.",["Both sides agree at 6."])]);

const limitTools = chapter("c-limit-tools","Limit Laws & Continuity","Calculate nearby behavior, diagnose discontinuities, and justify existence claims.",[
  section({id:"c-limit-algebra",title:"Substitution, Cancellation & Rationalization",teaches:["limit-laws","algebraic-limits"],requires:["limits-one-sided","rational-expressions","radicals"],
    paragraphs:["Limit laws let us combine known limits: sums, products, and constant multiples behave as expected. A quotient law requires a nonzero limiting denominator. Polynomial functions are continuous, so direct substitution works for them. Quotients of continuous functions allow substitution wherever the denominator is nonzero. Start by checking whether this simplest method is valid.","The symbol 0/0 is an indeterminate form, not an answer. It says substitution alone did not settle the limit. Factoring may reveal a common factor valid to cancel for nearby x≠a. A radical difference often benefits from multiplying by its conjugate. These changes need only preserve the function near the point; they do not repair or redefine the original function at the point."],
    rules:["Quotient limit law requires a nonzero denominator limit.","Cancel common factors, never separate terms of a sum.","(sqrt(A)-sqrt(B))(sqrt(A)+sqrt(B))=A-B."],
    examples:[{problem:"Find lim x→3 (x^2-9)/(x-3).",steps:["For x≠3, factor and cancel to obtain x+3.","The limit is 6; the original quotient is still undefined at 3."]},{problem:"Find lim x→0 (sqrt(4+x)-2)/x.",steps:["Multiply by the conjugate to get 1/(sqrt(4+x)+2) for x≠0.","Substitute 0 into the simplified nearby expression: 1/4."]}],
    misconception:"An indeterminate form requests more analysis; it does not mean zero or nonexistence.",
    questions:[n("c-law-1","Find lim x→-2 (3x^2+x-1).","9","A polynomial allows substitution.",["3(4)-2-1=9."]),n("c-law-2","Find lim x→1 (x+2)/(x^2+3).","3/4","Check the denominator limit first.",["The denominator approaches 4, so the limit is 3/4."]),n("c-law-3","Find lim x→4 (x^2-16)/(x-4).","8","Factor the numerator.",["For x≠4 the quotient is x+4; the limit is 8."]),n("c-law-4","Find lim x→-2 (x^2+5x+6)/(x+2).","1","Find a common binomial factor.",["(x+2)(x+3)/(x+2)=x+3 near -2, giving 1."]),n("c-law-5","Find lim x→1 (x^3-1)/(x-1).","3","Use x^3-1=(x-1)(x^2+x+1).",["The nearby quotient x^2+x+1 approaches 3."]),n("c-law-6","Find lim x→0 (sqrt(9+x)-3)/x.","1/6","Rationalize the difference.",["The quotient becomes 1/(sqrt(9+x)+3), tending to 1/6."]),n("c-law-7","Find lim x→2 ((1/x)-(1/2))/(x-2).","-1/4","Combine the small fractions before cancelling.",["(2-x)/(2x(x-2))=-1/(2x), tending to -1/4."]),pick("c-law-8","Direct substitution gives 0/0. Which conclusion is valid?","The method is inconclusive",["The limit is 0","The limit is infinity","The method is inconclusive"],"An indeterminate form is not a result.",["Analyze the nearby expression by another justified method."]) ]}),
  section({id:"c-infinite",title:"Infinite Limits & End Behavior",teaches:["infinite-limits"],requires:["algebraic-limits","rational-graphs"],
    paragraphs:["An infinite limit describes outputs that grow without bound in a specified direction. Saying f(x) tends to positive infinity does not assign the real number infinity to f(a). A vertical asymptote can have different signs on its two sides. Keep a sign chart for the factors that become small, and distinguish an odd power of a changing-sign factor from an even power.","Limits at infinity ask what happens as the input travels arbitrarily far left or right. For rational functions, divide numerator and denominator by the highest denominator power or compare leading terms. Equal degrees give a ratio of leading coefficients; a smaller numerator degree gives zero. Larger numerator degree needs its leading power and direction analyzed. Also remember sqrt(x^2)=|x|, especially for negative inputs."],
    rules:["1/u→+inf as u→0+ and →-inf as u→0-.","For rational functions with equal degrees, the end limit is the leading-coefficient ratio.","sqrt(x^2)=|x|, not x for negative x."],
    examples:[{problem:"Analyze 1/(x-2) as x approaches 2.",steps:["To the left the denominator is a small negative number: -inf.","To the right it is a small positive number: +inf; the two sides do not agree."]},{problem:"Find lim x→-inf sqrt(x^2+1)/x.",steps:["Write the numerator as |x|sqrt(1+1/x^2).", "For negative x, |x|/x=-1, so the limit is -1."]}],
    misconception:"A horizontal asymptote concerns large inputs, not a prohibition on the graph crossing that line.",
    questions:[pick("c-inf-1","Find lim x→3 from the right 1/(x-3).","+inf",["+inf","-inf","0"],"Track the sign of the small denominator.",["x-3 is positive and tends to zero."]),pick("c-inf-2","Find lim x→3 from the left 1/(x-3).","-inf",["+inf","-inf","0"],"The denominator is now negative.",["The reciprocal decreases without bound."]),pick("c-inf-3","Find the two-sided limit as x→3 of 1/(x-3)^2, allowing infinite-limit notation.","+inf",["+inf","-inf","DNE because the signs differ"],"Squaring changes the sign analysis.",["Both sides have a positive denominator approaching zero."]),n("c-inf-4","Find lim x→inf (5x^2-1)/(2x^2+7).","5/2","Divide by x^2.",["(5-1/x^2)/(2+7/x^2) tends to 5/2."]),n("c-inf-5","Find lim x→-inf (3x+2)/(x^2+1).","0","The denominator has higher degree.",["Dividing by x^2 leaves numerator terms tending to zero."]),n("c-inf-6","Find lim x→-inf sqrt(x^2+4)/x.","-1","Use the absolute value when extracting x^2.",["|x|/x=-1 on the negative side; the remaining root tends to 1."])]}),
  section({id:"c-continuity",title:"Continuity, IVT & Bisection",teaches:["continuity","intermediate-value","bisection"],requires:["limit-laws","infinite-limits"],
    paragraphs:["Continuity at a means three statements hold together: f(a) exists, the two-sided limit exists, and that limit equals f(a). At an endpoint of a domain, use the appropriate one-sided limit. A removable discontinuity can be repaired by defining the missing point to equal its limit. A jump cannot be repaired by changing only one point because the nearby sides already disagree.","The Intermediate Value Theorem says a continuous function on [a,b] takes every output between f(a) and f(b). Opposite endpoint signs therefore guarantee at least one zero inside. They do not guarantee exactly one zero. Bisection repeatedly checks the midpoint and keeps a half-interval whose endpoints have opposite signs. The continuity hypothesis makes this a reliable bracketing argument, not merely a numerical guess."],
    rules:["Continuity at a: lim x→a f(x)=f(a).","IVT requires continuity on the entire closed interval.","After one bisection, the interval width is halved; after n steps it is divided by 2^n."],
    examples:[{problem:"f(x)=kx+1 for x<2 and f(x)=x^2 for x≥2. Choose k for continuity.",steps:["The right value and limit at 2 are 4.","Require 2k+1=4, so k=3/2."]},{problem:"Bracket a root of f(x)=x^2-2 on [1,2] with one bisection.",steps:["At the midpoint 1.5, f=0.25; at 1, f=-1.","Keep [1,1.5], whose endpoint signs differ."]}],
    misconception:"Opposite signs alone do not imply a zero if a vertical asymptote lies between the endpoints.",
    questions:[n("c-cont-1","Define f(x)=(x^2-25)/(x-5) for x≠5. What value of f(5) makes it continuous?","10","Use the nearby simplified rule.",["x+5 approaches 10."]),n("c-cont-2","f(x)=kx+2 for x<1 and f(x)=x^2+4 for x≥1. Find k for continuity at 1.","3","Match the left limit to the right value.",["k+2=5, giving k=3."]),pick("c-cont-3","f is continuous on [0,2], with f(0)=-1 and f(2)=3. What must be true?","At least one zero lies in (0,2)",["Exactly one zero lies in (0,2)","At least one zero lies in (0,2)","f(1)=0"],"IVT guarantees existence, not uniqueness or a location.",["Zero lies between -1 and 3."]),pick("c-cont-4","Can opposite signs of 1/x at -1 and 1 prove a zero between them by IVT?","No: continuity fails on the interval",["Yes","No: continuity fails on the interval"],"Check the theorem's hypotheses.",["1/x is undefined at 0 and never equals zero."]),q("c-cont-5","For f(x)=x^2-3 on [1,2], perform one bisection and enter the retained interval endpoints.",[field("Left endpoint","1.5"),field("Right endpoint","2")],"Check the midpoint's sign.",["f(1.5)=-0.75 while f(2)=1, so retain [1.5,2]."]),n("c-cont-6","A bisection bracket starts with width 8. What is its width after 5 bisections?","1/4","Each step halves the width.",["8/2^5=1/4."])]})
],[n("c-limits-r1","Find lim x→-3 (x^2-9)/(x+3).","-6","Cancel a factor valid away from -3.",["The nearby expression x-3 tends to -6."]),n("c-limits-r2","Find lim x→inf (7x^3+x)/(2x^3-5).","7/2","Use the leading coefficients.",["Divide numerator and denominator by x^3."]),n("c-limits-r3","f(x)=x+4 for x<2 and f(x)=kx for x≥2. Find k for continuity.","3","The shared limiting height must be 6.",["2k=6, so k=3."])]);

const definition = chapter("c-derivative-definition","Derivatives from First Principles","Turn shrinking secant intervals into tangent slopes and derivative functions.",[
  section({id:"c-difference",title:"Difference Quotients & Tangent Lines",teaches:["derivative-definition","tangent-lines"],requires:["algebraic-limits","calculus-change"],
    paragraphs:["The derivative f'(a) is the limit of (f(a+h)-f(a))/h as h approaches zero, when that limit exists. Before taking the limit, h is nonzero and the quotient is a secant slope. The limit asks for the slope those secants approach as their endpoints come together. It does not ask you to divide by zero or to replace h by zero before simplifying.","A tangent line records the local direction of a curve at a specific point. Once its slope f'(a) and point (a,f(a)) are known, its equation is y=f(a)+f'(a)(x-a). The derivative is a rate with output units divided by input units. A tangent line usually approximates the curve only nearby; a matching point and slope do not mean the two functions agree everywhere."],
    rules:["f'(a)=lim h→0 [f(a+h)-f(a)]/h.","Tangent line: y=f(a)+f'(a)(x-a).","Keep h≠0 during cancellation, then take the limit."],
    examples:[{problem:"Find f'(2) from the definition for f(x)=x^2.",steps:["[(2+h)^2-4]/h=(4h+h^2)/h=4+h.","The limit is 4."]},{problem:"Find the tangent line to x^2 at x=2.",steps:["The point is (2,4) and the slope is 4.","y-4=4(x-2), or y=4x-4."]}],
    misconception:"A tangent is defined by local limiting slope; it can cross the curve at the contact point or elsewhere.",
    questions:[n("c-def-1","For f(x)=3x+2, evaluate [f(1+h)-f(1)]/h for any nonzero h.","3","The constant values cancel.",["(3+3h+2-5)/h=3."]),n("c-def-2","Use the definition to find f'(3) for f(x)=x^2.","6","Expand (3+h)^2.",["The quotient is 6+h, with limit 6."]),n("c-def-3","Use the definition to find f'(2) for f(x)=1/x.","-1/4","Combine fractions before cancelling h.",["[1/(2+h)-1/2]/h=-1/[2(2+h)], tending to -1/4."]),e("c-def-4","Give the y-expression for the tangent to y=x^2 at x=-1.","-2x-1","Use point (-1,1) and limiting slope -2.",["y-1=-2(x+1), hence y=-2x-1."]),n("c-def-5","The difference quotient for a function at a is 7+2h-h^2. Find f'(a).","7","Take its limit as h approaches zero.",["Both terms containing h tend to zero."]),e("c-def-6","A curve has f(3)=8 and f'(3)=-2. Give its tangent line's y-expression at x=3.","14-2*x","Use the point and slope, not just the slope.",["y=8-2(x-3)=14-2x."])]}),
  section({id:"c-differentiability",title:"The Derivative Function & When It Fails",teaches:["derivative-function","differentiability"],requires:["derivative-definition","continuity"],
    paragraphs:["Allowing the point a to vary produces a new function, f'(x). It assigns a tangent slope to each point where the derivative exists. For x^2, expanding (x+h)^2 and taking the limit gives f'(x)=2x: slopes are negative left of zero, zero at zero, and positive right of zero. A derivative graph plots slopes, not the heights of the original graph.","Differentiability at a point implies continuity there, but continuity alone does not guarantee differentiability. A corner can be continuous with different left and right slopes. An unbounded slope can create a vertical tangent without a finite derivative. A discontinuous function cannot be differentiable at the discontinuity. Always distinguish a derivative of zero from a derivative that does not exist."],
    rules:["For f(x)=x^2, the definition gives f'(x)=2x.","Differentiable implies continuous; the converse is false.","A finite derivative requires the left and right difference-quotient limits to agree."],
    examples:[{problem:"Analyze f(x)=|x| at x=0.",steps:["The function is continuous at 0.","Left slopes are -1 and right slopes are 1, so f'(0) does not exist."]},{problem:"Differentiate f(x)=x^2+3x using its difference quotient.",steps:["[f(x+h)-f(x)]/h=2x+h+3.","Taking h→0 yields f'(x)=2x+3."]}],
    misconception:"f'(a)=0 means a horizontal tangent, not automatically a highest or lowest value.",
    plot:{label:"The parabola y=x² and its derivative y=2x have different meanings: height versus slope",xRange:[-2,2],yRange:[-4,4],curves:[{expression:"x^2",label:"f(x)=x²"},{expression:"2*x",label:"f′(x)=2x"}]},
    questions:[e("c-diff-1","For f(x)=x^2-4x, its difference quotient simplifies to 2x+h-4. Give f'(x).","2*x-4","Let h approach zero.",["Only the h term vanishes, leaving 2x-4."]),pick("c-diff-2","Is |x| differentiable at 0?","No: the one-sided slopes disagree",["Yes: it is continuous","No: the one-sided slopes disagree"],"Compare the two slopes.",["The left derivative is -1 and the right is 1."]),pick("c-diff-3","If f is differentiable at a, which fact must follow?","f is continuous at a",["f(a)=0","f is continuous at a","f'(a)=0"],"Differentiability controls nearby function values.",["A finite difference quotient limit implies continuity."]),pick("c-diff-4","A curve is continuous at a but has an unbounded vertical slope there. Does a finite derivative exist?","No",["Yes, it equals 0","No"],"The usual derivative is a finite slope.",["An infinite slope is not a finite derivative."]),n("c-diff-5","A position derivative is v(t)=2t-4. At what time is its instantaneous velocity zero?","2","Solve the derivative equation.",["2t-4=0 gives t=2."]),pick("c-diff-6","A derivative graph lies below its horizontal axis on an interval. What does that say about the original function?","Its local slopes are negative",["Its values must be negative","Its local slopes are negative","Its values must be zero"],"Derivative height means original slope.",["Negative derivative values represent downward local slopes, regardless of original height."])]})
],[n("c-def-r1","For f(x)=2x^2, the difference quotient at a=3 is 12+2h. Find the derivative there.","12","Take h→0.",["The limit is 12."]),e("c-def-r2","f(2)=5 and f'(2)=3. Give the tangent line's y-expression.","3*x-1","Use y=5+3(x-2).",["The simplified line is 3x-1."]),pick("c-def-r3","A function has a jump at x=1. Can it be differentiable at 1?","No",["Yes, if f(1)=0","No"],"Use differentiability's necessary condition.",["A jump destroys continuity, so differentiability fails."])]);

const rules = chapter("c-derivative-rules","Differentiation Rules","Retrieve and combine rules while keeping the original function's structure visible.",[
  section({id:"c-power",title:"Power, Sum & Constant-Multiple Rules",teaches:["power-rule","higher-derivatives"],requires:["derivative-function","rational-exponents"],
    paragraphs:["The power rule compresses a limit calculation into a reusable result: the derivative of x^n is n*x^(n-1) wherever the real function and derivative are defined. It applies to positive integers and, on suitable domains, negative and fractional powers. Rewrite 1/x as x^(-1) and sqrt(x) as x^(1/2) before using the same rule. A constant function has derivative zero because its output never changes.","Differentiation respects addition and constant multiples, so a polynomial can be handled term by term. The exponent becomes a coefficient and then decreases by one; the old coefficient remains a multiplier. Differentiating the derivative produces a second derivative, which measures how the first rate changes. For position, the first derivative is velocity and the second is acceleration."],
    rules:["d(x^n)/dx=n*x^(n-1); d(c)/dx=0.","(af+bg)'=af'+bg' for constant a,b.","f'' is the derivative of f', not its square."],
    examples:[{problem:"Differentiate 4x^3-5x+8.",steps:["The terms give 12x^2, -5, and 0.","f'(x)=12x^2-5."]},{problem:"Differentiate sqrt(x) for x>0.",steps:["Write x^(1/2).", "The derivative is (1/2)x^(-1/2)=1/(2sqrt(x))."]}],
    misconception:"A constant disappears, but the derivative of cx is c, not zero.",
    questions:[e("c-power-1","Find the derivative of x^5.","5*x^4","Lower the exponent after multiplying by it.",["5x^(5-1)=5x^4."]),e("c-power-2","Differentiate 3x^4-2x^2+7x-9.","12*x^3-4*x+7","Differentiate term by term.",["The four derivatives are 12x^3, -4x, 7, and 0."]),n("c-power-3","What is the derivative of the constant function f(x)=17?","0","Its output never changes.",["Every difference quotient is zero."]),fn("c-power-4","Differentiate 1/x^3 for x≠0.","-3/x^4","Rewrite with a negative exponent.",["d(x^(-3))/dx=-3x^(-4)."]),fn("c-power-5","Differentiate sqrt(x) for x>0.","1/(2*sqrt(x))","Use exponent 1/2.",["(1/2)x^(-1/2)=1/(2sqrt(x))."]),fn("c-power-6","Differentiate x^(3/2) for x>0.","3*sqrt(x)/2","Subtract one from the exponent.",["(3/2)x^(1/2)."]),e("c-power-7","Find f''(x) for f(x)=2x^4-3x^2.","24*x^2-6","Differentiate twice.",["f'=8x^3-6x; f''=24x^2-6."]),n("c-power-8","s(t)=t^3-6t meters. Find acceleration at t=2 seconds.","12","Acceleration is the second derivative.",["v(t)=3t^2-6 and a(t)=6t; a(2)=12."])]}),
  section({id:"c-products",title:"Products & Quotients",teaches:["product-rule","quotient-rule"],requires:["power-rule"],
    paragraphs:["When both factors change, the derivative of a product has two contributions. Hold one factor while differentiating the other, then reverse roles: (uv)'=u'v+uv'. Multiplying the two derivatives loses both contributions and is generally wrong. Sometimes expanding a small polynomial product first is easier; both valid routes must agree.","For a quotient u/v, the derivative is (u'v-uv')/v^2 wherever v≠0. The order in the numerator matters: reversing the subtraction changes the sign. A constant denominator can instead be treated as a constant multiple. Simplify strategically, but do not cancel terms across addition. The original domain restrictions still belong to the differentiated function."],
    rules:["(uv)'=u'v+uv'.","(u/v)'=(u'v-uv')/v^2, v≠0.","Expansion before differentiation is valid when it preserves the function."],
    examples:[{problem:"Differentiate (x^2+1)(x-3).",steps:["Product rule: 2x(x-3)+(x^2+1).", "Collect terms to get 3x^2-6x+1."]},{problem:"Differentiate (x+1)/(x-1).",steps:["Numerator: (x-1)-(x+1)=-2.","The derivative is -2/(x-1)^2, with x≠1."]}],
    misconception:"The quotient rule is not u'/v'; that would ignore how the denominator changes.",
    questions:[e("c-prod-1","Differentiate x(x^2+4).","3*x^2+4","Expand or use the product rule.",["(x^2+4)+x(2x)=3x^2+4."]),e("c-prod-2","Differentiate (x^2-1)(x^2+1).","4*x^3","Two product contributions can cancel terms.",["2x(x^2+1)+2x(x^2-1)=4x^3."]),e("c-prod-3","Differentiate (2x+1)(x^2-3x).","6*x^2-10*x-3","Keep both contributions.",["2(x^2-3x)+(2x+1)(2x-3)=6x^2-10x-3."]),fn("c-prod-4","Differentiate (x+2)/(x-2), x≠2.","-4/(x-2)^2","Subtract in the quotient rule's order.",["[(x-2)-(x+2)]/(x-2)^2=-4/(x-2)^2."]),fn("c-prod-5","Differentiate x/(x^2+1).","(1-x^2)/(x^2+1)^2","The denominator must be squared.",["[(x^2+1)-2x^2]/(x^2+1)^2."]),n("c-prod-6","f(x)=x^2*g(x), with g(2)=3 and g'(2)=-1. Find f'(2).","8","Use both the known height and rate.",["f'=2xg+x^2g'; f'(2)=4(3)+4(-1)=8."]),n("c-prod-7","h=f/g. At x=1, f=6, f'=2, g=3, and g'=-1. Find h'(1).","4/3","Apply the quotient rule to the supplied values.",["(2·3-6·(-1))/3^2=12/9=4/3."])]}),
  section({id:"c-chain",title:"Composition & the Chain Rule",teaches:["chain-rule"],requires:["product-rule","quotient-rule","composition"],
    paragraphs:["A composition changes in layers. If y=f(g(x)), a small input change first changes g, then changes f through that intermediate value. The chain rule multiplies these two rates: f'(g(x))*g'(x). Differentiate the outer function while keeping its input intact, then multiply by the derivative of that input. Naming the inside temporarily can help, but the final answer returns to x.","Nested powers make the distinction between a power rule and a chain rule visible. The derivative of (3x+1)^4 is not merely 4(3x+1)^3; the inner input changes three times as quickly as x. With several layers, include every layer's derivative. Products and quotients can themselves contain compositions, so first identify the overall operation, then apply local rules to each piece."],
    rules:["d f(g(x))/dx=f'(g(x))*g'(x).","d [u(x)]^n/dx=n*u(x)^(n-1)*u'(x).","For sqrt(u), the derivative is u'/(2sqrt(u)) where u>0."],
    examples:[{problem:"Differentiate (2x-5)^3.",steps:["The outer derivative is 3(2x-5)^2.","Multiply by the inner derivative 2 to get 6(2x-5)^2."]},{problem:"Differentiate sqrt(x^2+4).",steps:["The inside derivative is 2x.","2x/(2sqrt(x^2+4))=x/sqrt(x^2+4)."]}],
    misconception:"Do not replace the inside by its derivative inside the original outer function; multiply by the inside derivative afterward.",
    questions:[fn("c-chain-1","Differentiate (3x+1)^4.","12*(3*x+1)^3","There is an inner slope of 3.",["4(3x+1)^3·3=12(3x+1)^3."]),fn("c-chain-2","Differentiate (x^2-2)^5.","10*x*(x^2-2)^4","Keep the inner expression when lowering the outer power.",["5(x^2-2)^4·2x."]),fn("c-chain-3","Differentiate sqrt(2x+1), for x>-1/2.","1/sqrt(2*x+1)","Include the inner derivative 2.",["2/(2sqrt(2x+1))=1/sqrt(2x+1)."]),fn("c-chain-4","Differentiate 1/(x^2+1).","-2*x/(x^2+1)^2","Treat the reciprocal as power -1.",["-(x^2+1)^(-2)·2x."]),fn("c-chain-5","Differentiate x(x^2+1)^3.","(x^2+1)^3+6*x^2*(x^2+1)^2","Use a product rule outside and a chain rule inside.",["The two contributions are (x^2+1)^3 and x·3(x^2+1)^2·2x."]),n("c-chain-6","h(x)=f(g(x)). Given g(2)=5, g'(2)=3, and f'(5)=-4, find h'(2).","-12","The outer derivative is evaluated at g(2).",["h'(2)=f'(5)g'(2)=(-4)3=-12."]),fn("c-chain-7","Differentiate ((x^2+1)^2+3)^2.","8*x*(x^2+1)*((x^2+1)^2+3)","There are three changing layers.",["2((x^2+1)^2+3)·2(x^2+1)·2x."])]})
],[fn("c-rules-r1","Differentiate (x^2+3)^4.","8*x*(x^2+3)^3","Use an outer power and inner quadratic derivative.",["4(x^2+3)^3·2x."]),fn("c-rules-r2","Differentiate (x^2+1)/(x+1), x≠-1.","(x^2+2*x-1)/(x+1)^2","Keep the subtraction order.",["[2x(x+1)-(x^2+1)]/(x+1)^2."]),n("c-rules-r3","s(t)=t^4-4t^2. Find acceleration at t=1.","4","Differentiate twice and then evaluate.",["s''(t)=12t^2-8; s''(1)=4."])]);

export const math1201: MathCourse = {
  id:"math1201",code:"MATH 1201",title:"Calculus I",
  description:"Limits, derivatives, optimization, accumulation, and integration through substantive lessons and typed mathematical practice.",
  prerequisites:[...new Set([...math1011.prerequisites,...math1011.units.flatMap(u=>u.chapters.flatMap(c=>c.sections.flatMap(s=>s.teaches)))])],
  sources:[{title:"Brooklyn College · MATH 1201 catalog scope",url:"https://websql.brooklyn.cuny.edu/courses/ShowCourse.do?crs_num=1201&div=U&dsc=MATH."},{title:"Brooklyn College · departmental Calculus I topic syllabus",url:"https://www.brooklyn.edu/wp-content/uploads/Math1201_Syllabus.pdf"}],
  units:[
    unit("c-unit1","I · Limits & Continuity",[approaching,limitTools],[
      n("c-u1-1","A particle has position s(t)=2t²+t meters. Find average velocity from t=1 to t=4 seconds.","11","Compare endpoint positions over elapsed time.",["s(4)=36, s(1)=3; (36-3)/3=11 m/s."]),
      n("c-u1-2","Evaluate lim (x²-25)/(x-5) as x→5.","10","Find the nearby rule without using the missing point.",["For x≠5 the quotient is x+5, tending to 10."]),
      n("c-u1-3","Evaluate lim (sqrt(x+9)-3)/x as x→0.","1/6","Use a conjugate.",["The nearby expression is 1/(sqrt(x+9)+3), whose limit is 1/6."]),
      q("c-u1-4","f(x)=2x+1 for x<2, and f(x)=kx-3 for x≥2. Find k for continuity and then f(2).",[field("k","4"),field("f(2)","5")],"Match the one-sided limits and the actual value.",["Left limit 5 must equal 2k-3, giving k=4 and f(2)=5."]),
      n("c-u1-5","Evaluate lim (7x²-x)/(2x²+5) as x→infinity.","7/2","Divide by the highest power of x.",["Lower-order terms vanish after division by x²."]),
      pick("c-u1-6","A function has left limit 4 and right limit -4 at x=1, while f(1)=0. What is its two-sided limit?","Does not exist",["0","4","-4","Does not exist"],"Both approaches must agree.",["The point value cannot reconcile unequal one-sided limits."]),
      pick("c-u1-7","A continuous function on [1,4] has f(1)=-3 and f(4)=2. What is guaranteed?","At least one zero in (1,4)",["Exactly one zero in (1,4)","At least one zero in (1,4)","No zero"],"Use the intermediate value theorem without adding uniqueness.",["Zero lies between the endpoint values, so at least one interior zero exists."])
    ]),
    unit("c-unit2","II · Derivative Foundations",[definition,rules],[
      n("c-u2-1","For f(x)=x²+2x, the difference quotient at x=4 is 10+h. Find f'(4).","10","Take the defining limit.",["As h→0 the quotient tends to 10."]),
      e("c-u2-2","Give the tangent line's y-expression for y=x³ at x=2.","12*x-16","Determine both contact height and slope.",["f(2)=8; f'(2)=12; y=8+12(x-2)=12x-16."]),
      fn("c-u2-3","Differentiate (x²+2)(3x-1).","9*x^2-2*x+6","Expansion or the product rule is valid.",["2x(3x-1)+3(x²+2)=9x²-2x+6."]),
      fn("c-u2-4","Differentiate (2x-1)/(x+3), x≠-3.","7/(x+3)^2","Keep the quotient-rule subtraction in order.",["[2(x+3)-(2x-1)]/(x+3)²=7/(x+3)²."]),
      fn("c-u2-5","Differentiate sqrt(3x+4), x>-4/3.","3/(2*sqrt(3*x+4))","Use the chain rule with a fractional power.",["(1/2)(3x+4)^(-1/2)·3."]),
      n("c-u2-6","s(t)=2t³-5t²+4 meters. Find acceleration at t=2 seconds.","14","Find the second derivative of position.",["s'=6t²-10t; s''=12t-10; s''(2)=14."]),
      pick("c-u2-7","A function is continuous at a point but has left derivative 2 and right derivative -1. Is it differentiable there?","No",["Yes","No"],"Finite one-sided slopes still have to agree.",["The unequal one-sided derivatives prevent a derivative at the point."])
    ]),
    unit("c-unit3","III · Transcendental Functions & Rates",[transcendental,rates],[
      fn("c-u3-1","Differentiate x cos(2x).","cos(2*x)-2*x*sin(2*x)","Identify the overall product and changing angle.",["cos(2x)+x(-sin(2x)·2)."]),
      fn("c-u3-2","Differentiate ln(4+x²)+e^(-x).","2*x/(4+x^2)-exp(-x)","Each term has an inner function.",["The log contributes 2x/(4+x²); the exponential contributes -e^(-x)."]),
      fn("c-u3-3","Differentiate atan(2x).","2/(1+4*x^2)","Include the inner derivative and square the input.",["2/(1+(2x)²)=2/(1+4x²)."]),
      n("c-u3-4","Find dy/dx for x²+xy=6 at (2,1).","-5/2","Differentiate the implicit relationship before substituting.",["2x+y+xy'=0, so y'=-(2x+y)/x=-5/2."]),
      n("c-u3-5","A sphere's radius is 4 cm and increases at 0.25 cm/s. Find its volume rate in cm³/s.","16*pi","Relate volume to radius.",["V'=4pi*r²*r'=4pi(16)(1/4)=16pi."]),
      n("c-u3-6","Use linearization at x=4 to estimate sqrt(3.96). Enter the linear estimate.","1.99","The input change is negative.",["2+(1/4)(-0.04)=1.99."]),
      n("c-u3-7","For y=x^x on x>0, find y' at x=e.","2*e^e","Take logs first, then restore y.",["y'=x^x(ln x+1); at e this is 2e^e."])
    ]),
    unit("c-unit4","IV · Derivative Applications",[extrema,applications],[
      q("c-u4-1","Find the absolute minimum and maximum values of f(x)=x²-2x on [-1,3].",[field("Minimum value","-1"),field("Maximum value","3")],"Compare both endpoints and the interior critical point.",["f(-1)=3, f(1)=-1, f(3)=3."]),
      n("c-u4-2","Find the MVT point c for f(x)=x² on [1,5].","3","Set derivative equal to average rate.",["Average slope=(25-1)/4=6; 2c=6 gives c=3."]),
      interval("c-u4-3","For f(x)=x³-12x, give all open intervals where f'(x)>0.","(-inf,-2) U (2,inf)","Use the signs of 3(x-2)(x+2).",["The product is positive outside its two zeros."]),
      q("c-u4-4","Find the inflection point of f(x)=x³-3x².",[field("x","1"),field("y","-2")],"Confirm a sign change of f''.",["f''=6x-6 changes sign at 1, where f(1)=-2."]),
      n("c-u4-5","A rectangle along a river is fenced on only three sides with 120 m of fence. Find its maximum area in m².","1800","Choose a width and express the remaining fenced side from the constraint.",["A=x(120-2x). The maximum is at x=30, with length 60 and area 1800."]),
      n("c-u4-6","Profit P(x)=50x-x²-100 dollars is modeled for 0≤x≤40. Find the maximum profit, not the production level.","525","Find the maximizing input and then evaluate the objective.",["P'=50-2x=0 at x=25; P(25)=1250-625-100=525."]),
      pick("c-u4-7","At a critical point, f' is negative on both sides. Is a local extremum established?","No",["Yes, a minimum","Yes, a maximum","No"],"The function continues in the same direction.",["There is no change from decreasing to increasing or the reverse."])
    ]),
    unit("c-unit5","V · Antiderivatives & Accumulation",[primitives,accumulation],[
      e("c-u5-1","F'(x)=4x³-2 and F(1)=6. Give F(x).","x^4-2*x+7","Recover the family and use the initial value.",["F=x⁴-2x+C; 6=1-2+C gives C=7."]),
      fn("c-u5-2","Find the nonconstant part of ∫(e^x-2sin(x)) dx. Omit +C.","exp(x)+2*cos(x)","Check signs by differentiating.",["e^x+2cos(x)+C has the required derivative."]),
      n("c-u5-3","a(t)=2 m/s², v(0)=3 m/s, and s(0)=-1 m. Find s(2) in meters.","9","Use both initial values.",["v=2t+3 and s=t²+3t-1; s(2)=9."]),
      n("c-u5-4","Position s(t)=t²-4t meters on [0,5] seconds. Find total distance.","13","Split the motion at t=2.",["Positions at 0,2,5 are 0,-4,5. Distance is 4+9=13."]),
      n("c-u5-5","Find R₂ for f(x)=x+2 on [0,4].","20","Width is 2 and the right inputs are 2 and 4.",["2(f(2)+f(4))=2(4+6)=20."]),
      n("c-u5-6","Given ∫_0^3 f=8 and ∫_3^7 f=-2, find ∫_7^0 f.","-6","Combine the intervals and reverse the bounds.",["∫_0^7 f=6, so the reverse integral is -6."]),
      q("c-u5-7","A curve has area 4 above the axis and 9 below over an interval. Give the integral and total area.",[field("Integral","-5"),field("Total area","13")],"Signed and unsigned accumulation differ.",["Integral=4-9=-5; total area=4+9=13."])
    ]),
    unit("c-unit6","VI · Fundamental Theorem & Substitution",[fundamental,substitution],[
      fn("c-u6-1","Differentiate A(x)=∫_1^(x³) cos(t) dt.","3*x^2*cos(x^3)","Use accumulation and the endpoint's rate.",["A'=cos(x³)·3x²."]),
      n("c-u6-2","Evaluate ∫_1^2 (3x²-2x) dx.","4","Use upper antiderivative value minus lower.",["[x³-x²]_1^2=(8-4)-(1-1)=4."]),
      fn("c-u6-3","Find the nonconstant part of ∫3x² e^(x³) dx. Omit +C.","exp(x^3)","Recognize the derivative of the exponent.",["u=x³ turns the integral into ∫e^u du."]),
      n("c-u6-4","Evaluate ∫_0^1 6x/(1+3x²) dx.","ln(4)","The denominator's derivative is the numerator.",["u=1+3x² changes the bounds to 1 and 4; ∫_1^4 du/u=ln4."]),
      n("c-u6-5","Find the average value of 2x+3 on [1,5].","9","Average accumulated value over the interval length.",["Integral=[x²+3x]_1^5=36; divide by 4 to get 9."]),
      n("c-u6-6","A tank starts at 12 L. Its net inflow is 2t e^(t²) L/min on [0,1]. Find the final amount.","11+e","Integrate the rate and add the initial amount.",["Change=e-1, so the final amount is 12+e-1=11+e."]),
      n("c-u6-7","A particle's velocity is v(t)=t-1 on [0,3]. Find total distance.","5/2","Split at the direction change, rather than taking net displacement.",["Distance is ∫_0^1 (1-t)dt+∫_1^3 (t-1)dt=1/2+2=5/2."])
    ])
  ]
};
